type PersonaSeed = {
  id: string;
  name: string;
  nameEn: string;
  group: string;
  groupEn: string;
  def: string;
  defEn: string;
  ontologyLevel?: 1 | 2 | 3 | 4 | 5;
  eras?: PersonaEra[];
  risk?: 'clean' | 'medium' | 'high';
  tags?: string[];
  styleTags?: string[];
  controls?: string[];
  forbids?: string[];
  absorptionRule?: string;
  absorptionRuleEn?: string;
  eraMode?: PersonaTerm['eraMode'];
  realityTags?: string[];
  categoryFit?: PersonaTerm['categoryFit'];
};

const baseControls = ['costume', 'symbol', 'prop', 'pose', 'material', 'ritual_mark'];
const defaultForbids = ['无解释现代街头化', '随机枪械抢走仪式身份', '喜剧化宗教符号', '过度消费网红化'];
const broadHistoricalEras: PersonaEra[] = ['feudal', 'early_modern', 'industrial', 'modern', 'contemporary'];
const mythicEras: PersonaEra[] = ['primitive', 'slave', 'feudal', 'mythic'];
const futureEras: PersonaEra[] = ['near_future', 'far_future'];

const ritualFit = (group: string): PersonaCategoryFit => {
  if (group.startsWith('A.')) return personaFit('weak', {
    strong: ['religious_ritual'],
    usable: ['dark_fantasy', 'historical', 'court'],
    fusion: ['horror', 'surreal'],
    weak: ['urban_life', 'wuxia', 'cyberpunk']
  });
  if (group.startsWith('B.')) return personaFit('weak', {
    strong: ['religious_ritual', 'dark_fantasy', 'horror'],
    usable: ['surreal', 'mythic_epic'],
    fusion: ['cosmic_horror', 'body_horror'],
    weak: ['urban_life', 'romance', 'fashion_idol']
  });
  if (group.startsWith('C.')) return personaFit('weak', {
    strong: ['religious_ritual', 'mythic_epic', 'ecological'],
    usable: ['fantasy', 'dark_fantasy', 'xianxia'],
    fusion: ['surreal', 'body_horror'],
    weak: ['cyberpunk', 'real_professional', 'fashion_idol']
  });
  if (group.startsWith('D.')) return personaFit('weak', {
    strong: ['xianxia', 'religious_ritual'],
    usable: ['wuxia', 'historical', 'mythic_epic'],
    fusion: ['dark_fantasy', 'surreal'],
    weak: ['urban_life', 'cyberpunk', 'wasteland']
  });
  if (group.startsWith('E.')) return personaFit('weak', {
    strong: ['religious_ritual', 'mythic_epic'],
    usable: ['historical', 'xianxia', 'urban_life'],
    fusion: ['dark_fantasy', 'surreal'],
    weak: ['war_military', 'wasteland', 'cyberpunk']
  });
  if (group.startsWith('F.')) return personaFit('weak', {
    strong: ['religious_ritual', 'wasteland'],
    usable: ['dark_fantasy', 'post_apocalyptic', 'horror'],
    fusion: ['science_fiction', 'surreal'],
    weak: ['romance', 'fashion_idol', 'court']
  });
  if (group.startsWith('G.')) return personaFit('weak', {
    strong: ['religious_ritual', 'mythic_epic'],
    usable: ['fantasy', 'xianxia', 'dark_fantasy'],
    fusion: ['surreal', 'science_fiction'],
    weak: ['real_professional', 'urban_life', 'wasteland']
  });
  if (group.startsWith('H.')) return personaFit('weak', {
    strong: ['religious_ritual'],
    usable: ['dark_fantasy', 'historical', 'horror'],
    fusion: ['surreal', 'wasteland'],
    weak: ['fashion_idol', 'cyberpunk', 'romance']
  });
  if (group.startsWith('I.')) return personaFit('weak', {
    strong: ['religious_ritual', 'fantasy'],
    usable: ['dark_fantasy', 'horror', 'historical'],
    fusion: ['surreal', 'xianxia'],
    weak: ['real_professional', 'urban_life', 'war_military']
  });
  return personaFit('weak', {
    strong: ['science_fiction', 'religious_ritual'],
    usable: ['cyberpunk', 'posthuman'],
    fusion: ['surreal', 'cosmic_horror', 'dark_fantasy'],
    weak: ['historical', 'wuxia', 'romance']
  });
};

