const rp = (seed: PersonaSeed): PersonaTerm => {
  const ontologyLevel = seed.ontologyLevel ?? 1;
  const eras = cleanPersonaEras(seed.eras ?? broadHistoricalEras);
  const risk = seed.risk ?? (ontologyLevel >= 4 ? 'medium' : 'clean');
  const controls = Array.from(new Set([...baseControls, ...(seed.controls || [])]));
  const eraMode = personaEraModeFor(eras, seed.eraMode);
  return {
    id: `cd_persona_ritual_${seed.id}`,
    name: seed.name,
    nameEn: seed.nameEn,
    group: seed.group,
    groupEn: seed.groupEn,
    def: seed.def,
    defEn: seed.defEn,
    personaCategory: '宗教 / 仪式神圣 / 神秘职能',
    personaCategoryEn: 'Religion / Ritual Sacred / Mystic Function',
    personaSubgroup: seed.group.replace(/^[A-J]\.\s*/, ''),
    personaSubgroupEn: seed.groupEn.replace(/^[A-J]\.\s*/, ''),
    personaKind: seed.name,
    personaKindEn: seed.nameEn,
    personaStrength: ontologyLevel >= 4 ? 'strong' : ontologyLevel >= 2 ? 'medium' : 'light',
    isCompoundPersona: true,
    ontologyLevel,
    eraMode,
    eras,
    risk,
    affects: controls,
    controls,
    forbids: Array.from(new Set([...(seed.forbids || []), ...defaultForbids])),
    absorptionRule: seed.absorptionRule || `外来元素优先折译为“${seed.name}”的服制、圣物/禁忌物、手势、身体标记、仪式流程或制度位置，不要直接堆成无关职业、随意怪物化或空泛神秘气氛。`,
    absorptionRuleEn: seed.absorptionRuleEn || `Translate outside elements into the dress, sacred/taboo objects, gestures, body marks, ritual workflow, or institutional position of "${seed.nameEn}"; do not stack them as unrelated jobs, arbitrary monster traits, or vague mystic mood.`,
    tags: Array.from(new Set(['persona', 'ritual', 'sacred', 'compound_persona', ...(seed.tags || [])])),
    realityTags: seed.realityTags || personaRealityTagsFor(ontologyLevel, ['ritual', 'sacred']),
    categoryFit: seed.categoryFit || ritualFitOverrides[seed.id] || ritualFit(seed.group),
    styleTags: Array.from(new Set(['ritual', 'sacred', ...(seed.styleTags || []), ...(seed.tags || [])])),
    timeTags: eras
  };
};

const seeds: PersonaSeed[] = [
  { id: 'gothic_priest', name: '哥特神父', nameEn: 'Gothic Priest', group: 'A. 天主教 / 哥特圣像', groupEn: 'A. Catholic / Gothic Icon', def: '第一识别是被黑色法衣和教堂阴影压低情绪的哥特神父。造型入口：高领黑袍、银十字、苍白面部、烛光边缘和替他人保管罪感的姿态。母题：信仰权威与私人阴影重叠。张力：他不能只是暗黑时装人物，必须让服制、手势和空间位置显示教会职能。视觉证据：法衣衣褶、念珠磨痕、烛台反光、低声祝祷的嘴、听忏悔时不完全直视的眼。边界：避免吸血鬼化或普通哥特模特。', defEn: 'First read: a gothic priest whose emotion is lowered by black vestments and church shadow. Styling entry: high-collar black robe, silver cross, pale face, candle edges, and posture keeping other people’s guilt. Motif: faith authority overlapping private darkness. Tension: he cannot be mere dark fashion; dress, gesture, and spatial position must show church function. Visual evidence: vestment folds, worn rosary, candle reflection, mouth in low blessing, and eyes not fully direct while hearing confession. Boundary: avoid vampire styling or generic goth model.', tags: ['catholic', 'gothic', 'priest'] },
  { id: 'mourning_nun', name: '丧服修女', nameEn: 'Mourning Nun', group: 'A. 天主教 / 哥特圣像', groupEn: 'A. Catholic / Gothic Icon', def: '第一识别是把悲伤制度化为安静身体的丧服修女。造型入口：黑白修女服、念珠、低头祈祷、克制袖口和像守夜一样的站姿。母题：个人哀悼被修会纪律吸收。张力：悲伤不能外放成哭戏，而要沉进衣层、手势和长时间静止。视觉证据：黑纱边、紧握念珠、白色头巾折线、微红眼眶、合掌手和不打扰死者的步伐。边界：避免恐怖修女或甜美圣洁模板。', defEn: 'First read: a mourning nun institutionalizing grief into a quiet body. Styling entry: black-white habit, rosary, lowered prayer, restrained cuffs, and a vigil-like stance. Motif: personal mourning absorbed by convent discipline. Tension: grief should not become crying drama, but sink into garment layers, gestures, and long stillness. Visual evidence: black veil edge, tightly held beads, white veil folds, faintly red eyes, pressed palms, and steps that do not disturb the dead. Boundary: avoid horror nun or sweet saintly template.', tags: ['nun', 'mourning', 'catholic'] },
  { id: 'cathedral_choir_boy', name: '教堂唱诗少年', nameEn: 'Cathedral Choir Boy', group: 'A. 天主教 / 哥特圣像', groupEn: 'A. Catholic / Gothic Icon', def: '第一识别是被穹顶回声和白色唱袍放大的教堂唱诗少年。造型入口：白色唱袍、乐谱、清冷脸、合唱队站位和被训练过的呼吸。母题：童声被教会空间塑造成神圣媒介。张力：纯净感来自仪式训练，不是可爱化。视觉证据：乐谱边角、领口阴影、并排站距、张口前的吸气、蜡光照亮的脸和不看观众的眼。边界：保持未成年边界，避免偶像化或成人化。', defEn: 'First read: a cathedral choir boy enlarged by dome echo and white robe. Styling entry: white choir robe, sheet music, cool face, choir placement, and trained breath. Motif: a child voice shaped by church space into sacred medium. Tension: purity comes from ritual training, not cuteness. Visual evidence: sheet-music corners, collar shadow, row spacing, breath before singing, candlelit face, and eyes not looking at the audience. Boundary: keep minor-safe boundaries and avoid idolization or adult framing.', ontologyLevel: 2, tags: ['choir', 'cathedral', 'boy'] },
  { id: 'confessional_keeper', name: '忏悔室守门人', nameEn: 'Confessional Keeper', group: 'A. 天主教 / 哥特圣像', groupEn: 'A. Catholic / Gothic Icon', def: '第一识别是守住罪感出口的忏悔室守门人。造型入口：木质隔窗、深色袍服、耳语姿态、钥匙串和半暗小室。母题：秘密被制度化保管。张力：亲密感很强，但必须由木栅、低声和礼仪距离控制。视觉证据：隔窗纹理、手中小钥匙、低头倾听、膝凳阴影、烛火反光和知道太多却不表态的眼。边界：避免色情化秘密或恐怖审讯。', defEn: 'First read: a confessional keeper guarding the exit of guilt. Styling entry: wooden grille, dark robe, whisper posture, key ring, and half-dark booth. Motif: secrets held by institution. Tension: intimacy is strong, but controlled by wooden screen, low voice, and ritual distance. Visual evidence: grille texture, small key in hand, lowered listening, kneeler shadow, candle reflection, and eyes that know too much without judging aloud. Boundary: avoid eroticizing secrecy or horror interrogation.', risk: 'medium', tags: ['confessional', 'keeper', 'guilt'] },
  { id: 'relic_bearer', name: '圣遗物携带者', nameEn: 'Relic Bearer', group: 'A. 天主教 / 哥特圣像', groupEn: 'A. Catholic / Gothic Icon', def: '第一识别是因托举圣物而变得庄严沉重的圣遗物携带者。造型入口：金属圣盒、白手套、黑袍、护送队列和不让圣盒倾斜的手。母题：身体成为神圣碎片的移动容器。张力：他本人不能抢走圣物中心，却必须显示承担重量和规训。视觉证据：圣盒锁扣、手套褶皱、低头行走、胸前距离、仪式步伐和看向圣盒而非观众的眼。边界：避免宝物炫耀或冒险者拾荒感。', defEn: 'First read: a relic bearer made solemn by carrying sacred remains. Styling entry: metal reliquary, white gloves, black robe, escort formation, and hands keeping the case level. Motif: the body as a moving container for a sacred fragment. Tension: he must not steal focus from the relic, yet must show weight and discipline. Visual evidence: reliquary lock, glove folds, lowered walk, distance at chest, ceremonial steps, and eyes looking at the case rather than viewers. Boundary: avoid treasure display or adventurer scavenger mood.', ontologyLevel: 2, tags: ['relic', 'bearer', 'sacred'] },
  { id: 'inquisitor_scholar', name: '审判庭学者', nameEn: 'Inquisitor Scholar', group: 'A. 天主教 / 哥特圣像', groupEn: 'A. Catholic / Gothic Icon', def: '第一识别是用知识执行信仰纪律的审判庭学者。造型入口：黑袍、旧书、银饰、审问记录和冷静到不近人情的坐姿。母题：学术文本变成审判工具。张力：危险来自他会读、会分类、会给人定罪，而不是外露暴力。视觉证据：批注书页、银质书签、文件蜡封、细长手指、桌面烛光和像检查文本一样检查人的眼。边界：避免普通神学教授或酷刑反派。', defEn: 'First read: an inquisitor scholar using knowledge to execute faith discipline. Styling entry: black robe, old books, silver ornaments, interrogation records, and a seated posture cold beyond empathy. Motif: scholarly text becoming a tool of judgment. Tension: danger comes from reading, classifying, and condemning, not from visible violence. Visual evidence: annotated pages, silver bookmark, wax-sealed files, long fingers, candlelit desk, and eyes examining people like texts. Boundary: avoid generic theology professor or torture villain.', risk: 'medium', tags: ['inquisitor', 'scholar', 'discipline'] },
  { id: 'baroque_saint_actor', name: '巴洛克圣徒扮演者', nameEn: 'Baroque Saint Actor', group: 'A. 天主教 / 哥特圣像', groupEn: 'A. Catholic / Gothic Icon', def: '第一识别是把身体摆成殉道图像的巴洛克圣徒扮演者。造型入口：金色刺绣、痛苦仰头、圣像姿势、戏剧衣褶和被光固定住的手。母题：宗教图像被表演身体复活。张力：情绪可以夸张，但必须像被仪式和画面构图严格摆放过。视觉证据：金线反光、仰颈曲线、手指张开、衣褶旋转、眼泪停在眼眶和像画中人一样的静止。边界：避免真实圣徒宣称或舞台狗血。', defEn: 'First read: a baroque saint actor arranging the body into martyr imagery. Styling entry: gold embroidery, pained upward head, icon posture, theatrical folds, and hands fixed by light. Motif: religious image revived through a performing body. Tension: emotion may be exaggerated, but must feel strictly placed by ritual and composition. Visual evidence: gold-thread shine, exposed neck curve, opened fingers, rotating folds, tears held at the eyes, and stillness like a painted figure. Boundary: avoid claiming real sainthood or stage melodrama.', ontologyLevel: 3, risk: 'medium', tags: ['baroque', 'saint', 'actor'] },
  { id: 'candle_procession_girl', name: '烛光游行少女', nameEn: 'Candle-Procession Girl', group: 'A. 天主教 / 哥特圣像', groupEn: 'A. Catholic / Gothic Icon', def: '第一识别是在集体祈祷队列里保持个人脸孔的烛光游行少女。造型入口：白衣、烛台、低声合唱、队列距离和小心护住火苗的手。母题：个体被温柔地纳入仪式群体。张力：她不能只是漂亮少女，必须显示正在学习如何让身体服从集体节奏。视觉证据：蜡泪、白袖、脚步间距、烛光照亮下巴、偷看旁人动作的眼。边界：保持未成年边界，避免偶像或恋爱化。', defEn: 'First read: a candle-procession girl keeping an individual face inside collective prayer. Styling entry: white dress, candleholder, low singing, procession spacing, and hands carefully protecting the flame. Motif: an individual gently absorbed by ritual group. Tension: she cannot be merely pretty; she must show the body learning collective rhythm. Visual evidence: candle wax tears, white sleeves, step spacing, candlelight under the chin, and eyes checking others’ motions. Boundary: keep minor-safe boundaries; avoid idol or romance framing.', tags: ['procession', 'candle', 'girl'] },
  { id: 'fallen_altar_server', name: '堕落祭坛侍童', nameEn: 'Fallen Altar Server', group: 'A. 天主教 / 哥特圣像', groupEn: 'A. Catholic / Gothic Icon', def: '第一识别是失去纯洁叙事后仍穿着祭坛服制残片的堕落祭坛侍童。造型入口：破损白袍、熄灭蜡烛、低垂眼神、烧黑袖口和被中断的礼仪动作。母题：曾经服务神圣的人被空洞感占据。张力：堕落不能变成怪物化，要保留他曾经被仪式训练过的证据。视觉证据：蜡烛烟痕、白袍污点、没说完的祷词、手停在胸前和不敢看祭坛的脸。边界：保持未成年边界，避免恐怖猎奇或性感化。', defEn: 'First read: a fallen altar server still wearing fragments of altar dress after losing the purity narrative. Styling entry: damaged white robe, extinguished candle, lowered gaze, scorched cuffs, and interrupted ritual motion. Motif: someone once serving the sacred now occupied by emptiness. Tension: falling must not become monsterization; evidence of former ritual training should remain. Visual evidence: candle smoke marks, stains on white robe, unfinished prayer, hand paused at the chest, and a face afraid to look at the altar. Boundary: keep minor-safe boundaries; avoid horror spectacle or sexualization.', ontologyLevel: 2, risk: 'medium', tags: ['altar_server', 'fallen', 'gothic'] },
  { id: 'modern_gothic_seminarian', name: '现代哥特神学院生', nameEn: 'Modern Gothic Seminarian', group: 'A. 天主教 / 哥特圣像', groupEn: 'A. Catholic / Gothic Icon', def: '第一识别是在现代城市里继续古老信仰训练的哥特神学院生。造型入口：黑色高领、神学书、银十字、地铁或宿舍光和过度自省的脸。母题：现代青年身体被古老教义慢慢塑形。张力：他不是潮流哥特，而是把信仰选择当成严肃训练的人。视觉证据：书页便签、十字项链藏在领口、通勤包、深夜阅读痕、眼下疲惫和面对城市噪声时收住的表情。边界：避免普通大学生或暗黑网红。', defEn: 'First read: a modern gothic seminarian continuing ancient faith training inside the city. Styling entry: black turtleneck, theology books, silver cross, subway or dorm light, and an over-introspective face. Motif: a modern youth body slowly shaped by old doctrine. Tension: he is not trendy goth, but someone treating faith choice as serious training. Visual evidence: page tabs, cross hidden at collar, commuter bag, late-night reading marks, tired under-eyes, and expression restrained before city noise. Boundary: avoid generic student or dark influencer.', tags: ['seminarian', 'modern', 'gothic'] },

  { id: 'dark_cult_adept', name: '黑暗教团学徒', nameEn: 'Dark-Cult Adept', group: 'B. 黑暗祭仪 / 禁忌教团', groupEn: 'B. Dark Ceremony / Taboo Order', def: '第一识别是刚进入禁忌秩序、还没有完全理解仪式的黑暗教团学徒。造型入口：编号黑袍、蜡封、禁忌符号、低头站位和紧张的手。母题：个人身份被秘密等级慢慢替换。张力：他不能显得已经掌控邪恶，而要显出服从、好奇和恐惧混合的入口状态。视觉证据：袍角编号、未拆蜡封、偷偷抬眼、手指捏住誓约纸和站在圆阵外圈的位置。边界：避免游戏反派皮肤或血腥猎奇。', defEn: 'First read: a dark-cult adept newly entering taboo order without fully understanding the ritual. Styling entry: numbered black robe, wax seal, taboo signs, lowered placement, and tense hands. Motif: personal identity slowly replaced by secret hierarchy. Tension: he should not seem to command evil yet, but show entry-state obedience, curiosity, and fear. Visual evidence: robe-hem number, unopened wax seal, stolen upward glance, fingers pinching oath paper, and position on the outer ring. Boundary: avoid game-villain skins or gore spectacle.', ontologyLevel: 3, eras: ['mythic'], risk: 'medium', tags: ['dark_cult', 'adept', 'taboo'] },
  { id: 'sacrificial_oracle', name: '献祭神谕者', nameEn: 'Sacrificial Oracle', group: 'B. 黑暗祭仪 / 禁忌教团', groupEn: 'B. Dark Ceremony / Taboo Order', def: '第一识别是被仪式消耗、用身体换取预言的献祭神谕者。造型入口：遮眼白布、血色细节、干裂嘴唇、含混预言姿态和被扶住的站立。母题：知识从身体损耗中被抽取。张力：神谕权力很强，但人物必须显出虚弱、被使用和难以自主的状态。视觉证据：遮眼布结、白布染边、旁人扶手、颤动嘴角、祭台边缘和像听见远处声音的侧脸。边界：避免露骨献祭场面或怪物化先知。', defEn: 'First read: a sacrificial oracle whose body is consumed in exchange for prophecy. Styling entry: covered eyes, blood-color details, cracked lips, ambiguous prophecy posture, and standing with support. Motif: knowledge extracted through bodily depletion. Tension: oracle authority is strong, but the figure must show weakness, use, and limited agency. Visual evidence: blindfold knot, stained white cloth edge, supporting hands, trembling mouth, altar edge, and profile listening to a distant voice. Boundary: avoid explicit sacrifice scenes or monsterized prophet treatment.', ontologyLevel: 3, eras: ['mythic'], risk: 'medium', tags: ['oracle', 'sacrifice', 'dark'] },
  { id: 'masked_ceremony_master', name: '面具祭仪主持', nameEn: 'Masked Ceremony Master', group: 'B. 黑暗祭仪 / 禁忌教团', groupEn: 'B. Dark Ceremony / Taboo Order', def: '第一识别是用面具和手势控制全场节奏的祭仪主持。造型入口：硬面具、长袍、手杖、静止手势和被所有人等待的中心位置。母题：个人面孔退场，仪式权威登场。张力：他的权力来自节奏控制，而不是夸张邪恶表情。视觉证据：面具无表情、手杖落点、袍袖弧线、圆阵朝向、让人停住的手掌和不露真实脸的沉默。边界：避免魔术师舞台感或随意邪教符号。', defEn: 'First read: a masked ceremony master controlling the room through mask and gesture. Styling entry: hard mask, long robe, staff, still gestures, and central placement everyone waits for. Motif: personal face exits so ritual authority can appear. Tension: his power comes from rhythm control, not exaggerated evil expression. Visual evidence: expressionless mask, staff placement, sleeve arc, circle orientation, palm stopping people, and silence without a real face. Boundary: avoid stage magician mood or random cult symbols.', ontologyLevel: 3, risk: 'medium', tags: ['masked', 'ceremony_master', 'ritual'] },
  { id: 'wax_seal_scribe', name: '蜡封誓约书记', nameEn: 'Wax-Seal Oath Scribe', group: 'B. 黑暗祭仪 / 禁忌教团', groupEn: 'B. Dark Ceremony / Taboo Order', def: '第一识别是把灵魂债务记录成文本的蜡封誓约书记。造型入口：黑墨、蜡封、誓约册、细笔和冷静到机械的手。母题：禁忌关系被文书化。张力：他看似只是书记，实际让誓言、惩罚和归属获得不可撤销的形式。视觉证据：滴落红蜡、签名格、黑色指尖、厚册页、封印印章和不看立誓者表情的眼。边界：避免普通秘书或法师抄写员。', defEn: 'First read: a wax-seal oath scribe recording soul debts as text. Styling entry: black ink, wax seals, oath book, fine pen, and mechanically calm hands. Motif: taboo relations turned into paperwork. Tension: he appears only a scribe, yet makes vows, punishment, and belonging irreversible. Visual evidence: dripping red wax, signature boxes, blackened fingertips, thick pages, seal stamp, and eyes not watching the swearer’s expression. Boundary: avoid generic secretary or mage copyist.', ontologyLevel: 3, risk: 'medium', tags: ['wax_seal', 'scribe', 'oath'] },
  { id: 'ash_covered_devotee', name: '覆灰信徒', nameEn: 'Ash-Covered Devotee', group: 'B. 黑暗祭仪 / 禁忌教团', groupEn: 'B. Dark Ceremony / Taboo Order', def: '第一识别是用灰烬把个人面孔擦除的覆灰信徒。造型入口：灰白皮肤、粗布袍、跪姿、低垂手和几乎没有个人装饰的身体。母题：自我抹除作为信仰证明。张力：服从要显得真实、疲惫、重复，而不是漂亮神秘妆。视觉证据：灰粉堆积、膝盖布料磨白、干裂嘴唇、抬不起的肩和跟随口令移动的眼。边界：避免时尚烟熏妆或怪物化。', defEn: 'First read: an ash-covered devotee using ash to erase the individual face. Styling entry: ash-white skin, coarse robe, kneeling posture, lowered hands, and a body almost without personal decoration. Motif: self-erasure as proof of belief. Tension: obedience should feel real, tired, and repeated, not like pretty mystic makeup. Visual evidence: ash accumulation, whitened fabric at knees, cracked lips, shoulders that cannot lift, and eyes moving only with commands. Boundary: avoid fashion smoky makeup or monsterization.', ontologyLevel: 3, risk: 'medium', tags: ['ash', 'devotee', 'obedience'] },
  { id: 'eclipse_ritual_bride', name: '日蚀祭仪新娘', nameEn: 'Eclipse Ritual Bride', group: 'B. 黑暗祭仪 / 禁忌教团', groupEn: 'B. Dark Ceremony / Taboo Order', def: '第一识别是婚礼被转化成宇宙献祭图像的日蚀祭仪新娘。造型入口：黑白婚纱、日蚀符号、静止微笑、遮面纱和不属于爱情的行进路线。母题：亲密仪式被教团夺走。张力：她必须像新娘又不像普通新娘，白色纯洁和黑色遮蔽同时存在。视觉证据：黑边头纱、圆形日蚀刺绣、手捧非花束、队列押送感和微笑里没有喜悦的脸。边界：避免普通哥特婚纱或恐怖新娘。', defEn: 'First read: an eclipse ritual bride whose wedding has been transformed into cosmic offering. Styling entry: black-white bridal dress, eclipse signs, still smile, face veil, and a procession route not belonging to romance. Motif: intimate ceremony taken over by a cult. Tension: she must read as bride and not an ordinary bride; white purity and black concealment coexist. Visual evidence: black-edged veil, circular eclipse embroidery, non-floral hand offering, escorted procession feeling, and a smile without joy. Boundary: avoid generic gothic bridalwear or horror bride.', ontologyLevel: 3, risk: 'medium', tags: ['eclipse', 'bride', 'ritual'] },
  { id: 'taboo_relic_collector', name: '禁忌圣物收藏者', nameEn: 'Taboo Relic Collector', group: 'B. 黑暗祭仪 / 禁忌教团', groupEn: 'B. Dark Ceremony / Taboo Order', def: '第一识别是把危险物件当知识收藏的禁忌圣物收藏者。造型入口：标本盒、黑手套、封印标签、记录卡和不愿离开藏品的目光。母题：好奇心变成占有和分类。张力：他不是寻宝者，而是用收藏秩序驯服禁忌。视觉证据：编号标签、玻璃盒反光、细镊子、密封柜、手套上的灰尘和看藏品比看人更温柔的眼。边界：避免博物馆管理员或冒险者。', defEn: 'First read: a taboo relic collector treating dangerous objects as knowledge collection. Styling entry: specimen boxes, black gloves, sealed labels, record cards, and eyes unwilling to leave the objects. Motif: curiosity turning into possession and classification. Tension: he is not a treasure hunter, but uses collecting order to tame taboo. Visual evidence: serial tags, glass-box reflection, fine tweezers, sealed cabinet, dust on gloves, and eyes softer toward objects than people. Boundary: avoid museum clerk or adventurer treatment.', ontologyLevel: 3, risk: 'medium', tags: ['taboo_relic', 'collector', 'sealed'] },
  { id: 'basement_cult_leader', name: '地下室教团领袖', nameEn: 'Basement Cult Leader', group: 'B. 黑暗祭仪 / 禁忌教团', groupEn: 'B. Dark Ceremony / Taboo Order', def: '第一识别是把普通人群带入危险信仰的地下室教团领袖。造型入口：普通西装、昏暗地下室、手写符号、折叠椅和过分亲切的控制力。母题：日常空间低成本地产生集体服从。张力：他不能像古代邪祭司，恐怖点在于太像现实里的说服者。视觉证据：白板口号、廉价咖啡杯、围坐人群、柔和笑容、停在成员肩上的手和不许人离开的眼。边界：避免魔王化或血腥仪式。', defEn: 'First read: a basement cult leader drawing ordinary people into dangerous faith. Styling entry: ordinary suit, dim basement, handwritten signs, folding chairs, and overly warm control. Motif: collective obedience produced cheaply inside daily space. Tension: he must not look like an ancient evil priest; the horror is that he resembles a real persuader. Visual evidence: whiteboard slogans, cheap coffee cup, seated circle, soft smile, hand paused on a member’s shoulder, and eyes that do not permit leaving. Boundary: avoid demon-lord treatment or bloody ritual spectacle.', ontologyLevel: 2, eras: ['modern', 'contemporary'], risk: 'medium', tags: ['cult_leader', 'basement', 'control'] },
  { id: 'silent_circle_member', name: '沉默圆阵成员', nameEn: 'Silent Circle Member', group: 'B. 黑暗祭仪 / 禁忌教团', groupEn: 'B. Dark Ceremony / Taboo Order', def: '第一识别是放弃个人身份进入集体仪式的沉默圆阵成员。造型入口：相同袍服、环形站位、遮脸、编号或无名牌和不主动移动的身体。母题：个人被队形吞没。张力：他不需要独特表情，恰恰要通过一致性制造不安。视觉证据：同款袖口、脚尖朝向中心、遮脸布、肩部间距、跟随前一人呼吸的节奏。边界：避免单独主角化或随机黑袍人。', defEn: 'First read: a silent circle member surrendering personal identity to collective ritual. Styling entry: matching robes, circular formation, covered face, number or no-name tag, and a body that does not move first. Motif: the individual swallowed by formation. Tension: he does not need unique expression; sameness creates unease. Visual evidence: matching cuffs, toes aimed toward center, face covering, shoulder spacing, and breathing rhythm following the person before him. Boundary: avoid making him a solo protagonist or random black-robed extra.', ontologyLevel: 2, risk: 'medium', tags: ['circle', 'silent', 'collective'] },
  { id: 'forbidden_star_priest', name: '禁星祭司', nameEn: 'Forbidden-Star Priest', group: 'B. 黑暗祭仪 / 禁忌教团', groupEn: 'B. Dark Ceremony / Taboo Order', def: '第一识别是信奉不可见星体的禁星祭司。造型入口：星图、黑金法衣、异常天象纹样、观测器和像长期仰望暗空后的脸。母题：宇宙尺度的禁忌神学。张力：他不是普通占星师，而是把不可见天体当作律法来源。视觉证据：反常星轨图、黑金刺绣、冷色眼下、手中天球仪、祭坛上空白圆盘和像听见宇宙噪声的停顿。边界：避免宇宙大场景吞掉人物。', defEn: 'First read: a forbidden-star priest devoted to invisible celestial bodies. Styling entry: star charts, black-gold vestment, abnormal celestial motifs, observer device, and a face shaped by long looking into dark sky. Motif: taboo theology at cosmic scale. Tension: he is not a normal astrologer, but treats unseen stars as the source of law. Visual evidence: abnormal star-track map, black-gold embroidery, cold under-eyes, celestial sphere in hand, blank disc on altar, and pauses as if hearing cosmic noise. Boundary: avoid cosmic spectacle swallowing the figure.', ontologyLevel: 4, eras: ['mythic'], risk: 'medium', tags: ['forbidden_star', 'priest', 'cosmic'] },

  { id: 'bone_shaman', name: '骨饰萨满', nameEn: 'Bone Shaman', group: 'C. 萨满 / 自然灵媒', groupEn: 'C. Shaman / Natural Medium', def: '第一识别是用骨饰和鼓声与祖灵交涉的骨饰萨满。造型入口：骨串、兽皮、烟雾、手鼓和进入出神状态时松开的肩颈。母题：身体与祖先材料交换。张力：神秘感要从材料和仪式劳动里出现，而不是泛自然风。视觉证据：骨饰碰撞痕、兽皮缝线、烟熏脸、鼓面磨损、闭眼晃动和听见别人听不见之物的表情。边界：避免奇幻德鲁伊或漂亮部落写真。', defEn: 'First read: a bone shaman negotiating with ancestor spirits through bone ornaments and drum. Styling entry: bone strings, hide, smoke, hand drum, and shoulders loosening into trance. Motif: exchange between body and ancestor materials. Tension: mystery must emerge from material and ritual labor, not generic nature mood. Visual evidence: bone impact marks, hide stitching, smoke-darkened face, worn drumhead, closed-eye swaying, and expression hearing what others cannot. Boundary: avoid fantasy druid or pretty tribal portrait.', ontologyLevel: 2, eras: mythicEras, tags: ['shaman', 'bone', 'ancestor'] },
  { id: 'trance_drummer', name: '出神鼓手', nameEn: 'Trance Drummer', group: 'C. 萨满 / 自然灵媒', groupEn: 'C. Shaman / Natural Medium', def: '第一识别是把重复节奏敲成通灵通道的出神鼓手。造型入口：手鼓、闭眼、反复手腕动作、汗湿额头和围绕身体的听众距离。母题：节奏先改变身体，再改变场域。张力：他不是乐手表演，而是在用声音把意识推离日常。视觉证据：鼓槌磨损、手腕发红、呼吸变深、脚步小幅循环、旁人安静等待和表情逐渐失焦。边界：避免演唱会鼓手或抽象音效。', defEn: 'First read: a trance drummer turning repetition into a spirit channel. Styling entry: hand drum, closed eyes, repeated wrist motion, sweaty brow, and listener distance around the body. Motif: rhythm changes the body before it changes the field. Tension: he is not performing as a musician, but using sound to push consciousness out of daily life. Visual evidence: worn beater, reddened wrist, deepening breath, small circular footwork, quiet waiting people, and expression slowly losing focus. Boundary: avoid concert drummer or abstract sound effects.', ontologyLevel: 2, eras: mythicEras, tags: ['drum', 'trance', 'medium'] },
  { id: 'feather_oracle', name: '羽冠灵媒', nameEn: 'Feathered Oracle', group: 'C. 萨满 / 自然灵媒', groupEn: 'C. Shaman / Natural Medium', def: '第一识别是用羽冠和风向接收自然征兆的羽冠灵媒。造型入口：羽冠、彩绘面部、风中站姿、轻薄披挂和始终偏向天空的眼。母题：天空材料进入身体装饰。张力：神谕感不能变成美丽头饰展示，要让风、羽毛和等待共同形成读取姿态。视觉证据：羽毛方向、面部彩绘裂纹、手指摸风、侧耳倾听、站在高处边缘和缓慢开口前的停顿。边界：避免泛印第安装饰或时尚羽毛造型。', defEn: 'First read: a feathered oracle receiving natural signs through feather crown and wind direction. Styling entry: feather crown, painted face, wind posture, light drape, and eyes always angled toward sky. Motif: sky material entering body decoration. Tension: oracle feeling must not become beautiful headpiece display; wind, feathers, and waiting should form the reading posture together. Visual evidence: feather direction, cracked face paint, fingers touching air, listening profile, standing at a high edge, and pause before speaking. Boundary: avoid generic Indigenous-costume decoration or fashion feather styling.', ontologyLevel: 3, eras: mythicEras, tags: ['feather', 'oracle', 'nature'] },
  { id: 'forest_healer_witch', name: '森林疗愈巫者', nameEn: 'Forest Healer-Witch', group: 'C. 萨满 / 自然灵媒', groupEn: 'C. Shaman / Natural Medium', def: '第一识别是在村落边缘照护身体与灵魂的森林疗愈巫者。造型入口：草药包、树皮色衣物、温和皱纹、旧篮子和长期采集留下的手。母题：医疗、民间信仰和森林材料交叠。张力：她不是奇幻法师，疗愈来自经验、草药和被村人半信半疑地需要。视觉证据：药草束、泥色裙摆、木勺、手背割痕、递药时的安静眼神和站在屋外门槛的位置。边界：避免森林仙女或空泛疗愈海报。', defEn: 'First read: a forest healer-witch caring for body and soul at the village edge. Styling entry: herb pouch, bark-colored clothing, gentle wrinkles, old basket, and hands marked by long gathering. Motif: medicine, folk belief, and forest materials overlapping. Tension: she is not a fantasy mage; healing comes from experience, herbs, and being half-trusted, half-needed by villagers. Visual evidence: herb bundles, mud-colored hem, wooden spoon, cuts on hand backs, quiet eyes while offering medicine, and placement at the doorway outside. Boundary: avoid forest fairy or vague healing poster.', ontologyLevel: 2, eras: mythicEras, tags: ['forest', 'healer', 'witch'] },
  { id: 'animal_mask_medium', name: '兽面灵媒', nameEn: 'Animal-Mask Medium', group: 'C. 萨满 / 自然灵媒', groupEn: 'C. Shaman / Natural Medium', def: '第一识别是通过兽面让身体暂时成为兽灵通道的灵媒。造型入口：动物面具、毛皮、低伏姿态、爪痕装饰和不同于人类站姿的重心。母题：人形主体借用动物感知。张力：他不能真的变成兽，要保持面具、姿态和仪式边界。视觉证据：面具内阴影、毛皮缝合、弯曲背线、手指贴地、旁人让出的空间和像闻气味一样的侧脸。边界：避免兽化怪物或可爱动物拟人。', defEn: 'First read: an animal-mask medium whose body temporarily becomes a passage for animal spirit. Styling entry: animal mask, fur, crouched posture, claw-mark decoration, and nonhuman weight distribution. Motif: a humanoid subject borrowing animal perception. Tension: he must not truly become beast; mask, posture, and ritual boundary should remain. Visual evidence: shadow inside mask, fur stitching, curved back line, fingers near ground, space cleared by others, and profile as if smelling the air. Boundary: avoid beast monsterization or cute animal anthropomorphism.', ontologyLevel: 3, eras: mythicEras, risk: 'medium', tags: ['animal_mask', 'medium', 'spirit'] },
  { id: 'river_spirit_speaker', name: '河灵传话人', nameEn: 'River-Spirit Speaker', group: 'C. 萨满 / 自然灵媒', groupEn: 'C. Shaman / Natural Medium', def: '第一识别是站在人群与水域之间的河灵传话人。造型入口：湿布、贝壳、河泥标记、半卷裤脚和长期听水声形成的侧耳姿态。母题：水域边界被人格化为职能。张力：他不是水神，而是替水说话、替村人听水的人。视觉证据：湿发边缘、泥纹、贝壳串、河岸脚印、手指触水、讲完话后不看人的眼。边界：避免美人鱼化或大水景喧宾夺主。', defEn: 'First read: a river-spirit speaker standing between people and water. Styling entry: wet cloth, shells, river-mud marks, half-rolled trousers, and a profile shaped by listening to water. Motif: water boundary personified as function. Tension: he is not a water deity, but someone speaking for water and listening on behalf of villagers. Visual evidence: wet hair edge, mud lines, shell string, riverbank footprints, fingers touching water, and eyes not looking at people after speaking. Boundary: avoid mermaid treatment or huge water scenery overpowering the figure.', ontologyLevel: 3, eras: mythicEras, tags: ['river', 'spirit', 'speaker'] },
  { id: 'desert_rain_caller', name: '沙漠祈雨者', nameEn: 'Desert Rain Caller', group: 'C. 萨满 / 自然灵媒', groupEn: 'C. Shaman / Natural Medium', def: '第一识别是把稀缺水源神圣化的沙漠祈雨者。造型入口：干裂皮肤、蓝色布条、沙尘鼓、空水袋和仰望云迹的身体。母题：干旱环境里对水的集体期待。张力：他不能像万能法师，祈雨更像长期失败后仍要继续的公共职责。视觉证据：裂纹唇、蓝布褪色、鼓面沙粒、空碗、晒黑手臂和在热风里保持仪式步伐的脚。边界：避免奇迹降雨大场面或旅游沙漠装。', defEn: 'First read: a desert rain caller sanctifying scarce water. Styling entry: cracked skin, blue cloth strips, sand-dust drum, empty waterskin, and a body looking for cloud traces. Motif: collective expectation for water in drought. Tension: he cannot be an all-powerful mage; rain calling feels like public duty continued after many failures. Visual evidence: cracked lips, faded blue cloth, sand on drumhead, empty bowl, sun-dark arms, and feet keeping ritual steps in hot wind. Boundary: avoid miracle-rain spectacle or tourist desert costume.', ontologyLevel: 3, eras: mythicEras, tags: ['desert', 'rain_caller', 'water'] },
  { id: 'ancestor_mask_keeper', name: '祖灵面具守护者', nameEn: 'Ancestor-Mask Keeper', group: 'C. 萨满 / 自然灵媒', groupEn: 'C. Shaman / Natural Medium', def: '第一识别是替族群记忆保管旧木面具的祖灵面具守护者。造型入口：旧木面具、烟熏痕、安静双手、面具架和不轻易触碰的距离。母题：祖先记忆被物件和照护动作延续。张力：他不是表演者，权力来自保管、清洁、修补和知道何时不能使用。视觉证据：木纹裂缝、烟灰沉积、包裹布、双手托举、面具内侧暗影和看向年轻人的提醒眼神。边界：避免面具怪物或博物馆陈列员。', defEn: 'First read: an ancestor-mask keeper preserving old wooden masks for group memory. Styling entry: old wooden masks, smoke marks, quiet hands, mask stand, and distance before touching. Motif: ancestor memory continued through objects and care actions. Tension: he is not a performer; power comes from keeping, cleaning, repairing, and knowing when not to use. Visual evidence: wood cracks, ash deposits, wrapping cloth, two-handed carrying, shadow inside masks, and eyes warning the young. Boundary: avoid mask monster or museum display clerk.', ontologyLevel: 2, eras: mythicEras, tags: ['ancestor', 'mask', 'keeper'] },
  { id: 'fungal_trance_shaman', name: '菌群出神萨满', nameEn: 'Fungal-Trance Shaman', group: 'C. 萨满 / 自然灵媒', groupEn: 'C. Shaman / Natural Medium', def: '第一识别是通过菌群进入幻视的菌群出神萨满。造型入口：蘑菇纹样、孢子袋、潮湿衣物、低伏身体和像在听地下网络的神情。母题：非动物生命成为通灵接口。张力：超现实感要来自共生、潮湿和感知偏移，不要变成感染怪物。视觉证据：衣摆潮斑、孢子粉、菌伞图案、指尖触地、呼吸变慢和瞳孔像失焦一样散开。边界：避免寄生恐怖或纯植物人。', defEn: 'First read: a fungal-trance shaman entering visions through fungal networks. Styling entry: mushroom motifs, spore pouch, damp clothing, low body, and expression listening to an underground network. Motif: non-animal life as medium interface. Tension: surreal feeling should come from symbiosis, dampness, and shifted perception, not infection monster traits. Visual evidence: damp stains on hem, spore powder, cap patterns, fingertips on ground, slowed breath, and pupils spreading out of focus. Boundary: avoid parasite horror or pure plant person.', ontologyLevel: 4, eras: ['primitive', 'feudal', 'mythic'], risk: 'medium', tags: ['fungal', 'trance', 'shaman'] },
  { id: 'urban_neoshaman', name: '都市新萨满', nameEn: 'Urban Neo-Shaman', group: 'C. 萨满 / 自然灵媒', groupEn: 'C. Shaman / Natural Medium', def: '第一识别是把城市噪声转成通灵节奏的都市新萨满。造型入口：耳机、羽毛饰物、涂鸦墙、电子鼓点控制器和介于街头与仪式之间的衣层。母题：传统出神技术在城市声场中重组。张力：他不是潮流DJ，必须让身体像在调和交通、广告牌和人群噪声。视觉证据：线缆、手鼓贴纸、羽毛耳饰、霓虹反光、闭眼听路口节奏的脸和不看手机却跟着节拍移动的手。边界：避免夜店DJ或网红灵性摆拍。', defEn: 'First read: an urban neo-shaman turning city noise into trance rhythm. Styling entry: headphones, feather accessory, graffiti wall, electronic beat controller, and layers between streetwear and ritual. Motif: traditional trance techniques recomposed inside the urban sound field. Tension: he is not a trendy DJ; the body should look like it is tuning traffic, billboards, and crowd noise. Visual evidence: cables, drum stickers, feather earring, neon reflection, face listening to intersection rhythm with closed eyes, and hands moving to a beat without looking at a phone. Boundary: avoid nightclub DJ or influencer spirituality posing.', ontologyLevel: 2, eras: ['contemporary', 'near_future'], tags: ['neo_shaman', 'urban', 'trance'] },

  { id: 'daoist_talisman_master', name: '符箓道士', nameEn: 'Daoist Talisman Master', group: 'D. 道教 / 东亚法脉', groupEn: 'D. Daoist / East Asian Lineage', def: '第一识别是通过符纸和法印把秩序写进世界的符箓道士。造型入口：道袍、黄符、朱砂、法印、清瘦站姿和干净袖口。母题：文字、墨色和仪式手势共同执行法度。张力：神秘性必须固定在具体法器和流程里，不要只靠东方气氛。视觉证据：符纸折角、朱砂指痕、法印盒、袖中符册、悬腕书写和像在校准空间的眼。边界：避免泛古风美人或仙侠特效。', defEn: 'First read: a Daoist talisman master writing order into the world through charms and seals. Styling entry: Daoist robe, yellow talismans, cinnabar, ritual seal, lean stance, and clean cuffs. Motif: text, pigment, and ritual gesture executing order together. Tension: mystery must be fixed in concrete tools and workflow, not vague oriental mood. Visual evidence: folded talisman corners, cinnabar on fingers, seal case, charm booklet in sleeve, suspended wrist writing, and eyes as if calibrating space. Boundary: avoid generic period beauty or xianxia VFX.', ontologyLevel: 2, eras: ['feudal', 'early_modern', 'modern'], tags: ['daoist', 'talisman', 'lineage'] },
  { id: 'ritual_sword_priest', name: '法剑道人', nameEn: 'Ritual-Sword Daoist', group: 'D. 道教 / 东亚法脉', groupEn: 'D. Daoist / East Asian Lineage', def: '第一识别是用法剑和步罡动作划定秩序的法剑道人。造型入口：桃木剑、道冠、黄符、步罡路线和向空间发号施令的身体。母题：剑不是武器，而是仪式测量工具。张力：动作要有法度和方向，不是打斗或飞剑奇观。视觉证据：桃木剑纹理、脚下方位、袍袖摆动、符纸贴位、眼神盯住空间节点和剑尖停在空气里的瞬间。边界：避免武侠剑客或法术特效堆叠。', defEn: 'First read: a ritual-sword Daoist defining order through sword and ritual stepping. Styling entry: peachwood sword, Daoist crown, yellow talismans, step-path, and a body commanding space. Motif: the sword as ritual measuring tool rather than weapon. Tension: movement needs order and direction, not combat or flying-sword spectacle. Visual evidence: peachwood texture, directional foot placement, sleeve swing, charm placement, eyes fixed on spatial nodes, and sword tip paused in air. Boundary: avoid wuxia swordsman or stacked spell effects.', ontologyLevel: 2, eras: ['feudal', 'early_modern', 'modern'], tags: ['ritual_sword', 'daoist', 'order'] },
  { id: 'mountain_hermit_adept', name: '山中修行道人', nameEn: 'Mountain Hermit Adept', group: 'D. 道教 / 东亚法脉', groupEn: 'D. Daoist / East Asian Lineage', def: '第一识别是远离尘世、把生活本身变成修行的山中道人。造型入口：旧道袍、草鞋、竹杖、清瘦身体和被山风磨旧的衣料。母题：退隐不是逃避，而是长期身体节制。张力：他不需要显神通，修行气来自简化需求和反复行走。视觉证据：草鞋磨损、竹杖手油、衣摆尘土、干净但粗糙的手、山路站姿和不急着回答的眼。边界：避免仙人飘浮或旅游隐士。', defEn: 'First read: a mountain hermit adept turning life itself into practice away from the world. Styling entry: old Daoist robe, straw sandals, bamboo staff, lean body, and fabric worn by mountain wind. Motif: withdrawal as long-term bodily restraint, not escape. Tension: he needs no miracle display; cultivation comes from reduced needs and repeated walking. Visual evidence: worn sandals, hand-oiled bamboo staff, dusty hem, clean but rough hands, mountain-path stance, and eyes not rushing to answer. Boundary: avoid floating immortal or tourist hermit.', ontologyLevel: 2, eras: ['feudal', 'mythic'], tags: ['hermit', 'daoist', 'mountain'] },
  { id: 'temple_incense_keeper', name: '香火庙祝', nameEn: 'Temple Incense Keeper', group: 'D. 道教 / 东亚法脉', groupEn: 'D. Daoist / East Asian Lineage', def: '第一识别是管理民间祈愿日常流动的香火庙祝。造型入口：香灰、签筒、木桌、旧庙灯光和被烟熏久了的衣袖。母题：神圣通过维护、接待和小额愿望运转。张力：他不是高法力道士，而是让庙每天继续被使用的人。视觉证据：香灰指尖、签筒磨损、功德箱、旧账本、递签时的熟练手和听愿望听到麻木的眼。边界：避免神仙化或普通店员化。', defEn: 'First read: a temple incense keeper managing the daily flow of folk wishes. Styling entry: incense ash, divination sticks, wooden table, old temple light, and sleeves long smoked by incense. Motif: sacredness operating through maintenance, reception, and small wishes. Tension: he is not a high-magic Daoist, but the person keeping the temple usable every day. Visual evidence: ash on fingertips, worn stick tube, donation box, old ledger, skilled hand passing sticks, and eyes numbed by hearing wishes. Boundary: avoid deification or generic shop clerk treatment.', eras: ['feudal', 'modern', 'contemporary'], tags: ['temple', 'incense', 'keeper'] },
  { id: 'paper_charm_exorcist', name: '纸符驱邪人', nameEn: 'Paper-Charm Exorcist', group: 'D. 道教 / 东亚法脉', groupEn: 'D. Daoist / East Asian Lineage', def: '第一识别是用纸符把异常压回秩序的民间驱邪人。造型入口：纸符、铜钱剑、黑布包、朱砂盒和熟悉家宅角落的身体。母题：小型异常被社区法术处理。张力：不要变成大战妖魔，重点是门槛、床脚、灶台这些现实位置上的修补。视觉证据：贴在门框的符、铜钱剑绳结、黑布包磨损、低声念词、蹲下查看地面的眼。边界：避免恐怖片驱魔或仙侠斗法。', defEn: 'First read: a paper-charm exorcist pushing anomalies back into order with talismans. Styling entry: paper charms, coin sword, black cloth bag, cinnabar box, and a body familiar with house corners. Motif: small anomalies handled by community folk ritual. Tension: do not turn it into monster battles; focus on doorways, bed legs, stoves, and other real locations being repaired. Visual evidence: charm on doorframe, coin-sword knots, worn black pouch, low chanting, and eyes crouching to inspect the floor. Boundary: avoid horror exorcist or xianxia duel.', ontologyLevel: 3, eras: ['feudal', 'modern'], risk: 'medium', tags: ['exorcist', 'paper_charm', 'folk_magic'] },
  { id: 'fengshui_master', name: '风水先生', nameEn: 'Feng-Shui Master', group: 'D. 道教 / 东亚法脉', groupEn: 'D. Daoist / East Asian Lineage', def: '第一识别是把空间读成命运结构的风水先生。造型入口：罗盘、长衫、地形图、卷尺和对门窗方位异常敏感的眼。母题：生活空间被解释为秩序和风险。张力：他不是神棍标签，而是用具体测量、方位和客户关系工作的人。视觉证据：罗盘刻度、图纸折痕、指向门口的手、低头计算、客户在旁等待和判断格局时收紧的嘴角。边界：避免玄学网红或空泛东方符号。', defEn: 'First read: a feng-shui master reading space as fate structure. Styling entry: compass, long gown, terrain map, measuring tape, and eyes sensitive to door and window direction. Motif: living space interpreted as order and risk. Tension: he is not an occult label, but someone working through measurement, orientation, and client relation. Visual evidence: compass marks, folded drawings, hand pointing to the door, lowered calculation, client waiting nearby, and mouth tightening while judging layout. Boundary: avoid occult influencer or vague oriental signs.', eras: ['feudal', 'modern', 'contemporary'], tags: ['fengshui', 'master', 'space'] },
  { id: 'funeral_taoist_priest', name: '丧仪道士', nameEn: 'Funeral Daoist Priest', group: 'D. 道教 / 东亚法脉', groupEn: 'D. Daoist / East Asian Lineage', def: '第一识别是在丧仪中引导死亡过渡的道士。造型入口：丧仪法袍、铃、纸钱、低声诵念和长期面对家属悲伤的疲惫脸。母题：死亡被法事流程带过边界。张力：他不是恐怖人物，而是职业化处理失去和秩序的人。视觉证据：铃铛磨痕、纸钱堆、法袍白边、灵堂光、低头念诵的嘴和不被哭声打乱的手。边界：避免鬼怪猎奇或普通葬礼司仪。', defEn: 'First read: a funeral Daoist priest guiding death’s transition through rites. Styling entry: funeral robe, bell, paper money, low chanting, and a tired face long facing family grief. Motif: death moved across boundary by ritual workflow. Tension: he is not a horror figure, but a professional handling loss and order. Visual evidence: worn bell, paper-money pile, white robe edge, mourning-hall light, mouth chanting low, and hands not disturbed by crying. Boundary: avoid ghost spectacle or generic funeral host.', ontologyLevel: 2, eras: ['feudal', 'modern', 'contemporary'], tags: ['funeral', 'daoist', 'death'] },
  { id: 'young_talisman_student', name: '年轻符箓学徒', nameEn: 'Young Talisman Student', group: 'D. 道教 / 东亚法脉', groupEn: 'D. Daoist / East Asian Lineage', def: '第一识别是刚进入法脉、认真到有点紧张的年轻符箓学徒。造型入口：练习符纸、墨迹手指、稍乱道袍、翻错页的符册和不敢浪费朱砂的手。母题：仪式知识尚未熟练地进入身体。张力：他不应像天才法师，而应像正在被规矩训练的新人。视觉证据：歪掉的符线、袖口墨点、咬唇专注、师父留下的批注和写完后偷偷看结果的眼。边界：避免少年英雄或搞笑道童。', defEn: 'First read: a young talisman student newly entering the lineage, serious enough to be nervous. Styling entry: practice talismans, inked fingers, slightly messy robe, wrong page in the charm book, and hands afraid to waste cinnabar. Motif: ritual knowledge not yet fully settled into the body. Tension: he should not be a genius mage, but a beginner being trained by rules. Visual evidence: crooked charm lines, ink dots on cuffs, focused lip bite, teacher annotations, and eyes secretly checking the result after writing. Boundary: avoid boy hero or comic novice monk.', ontologyLevel: 2, tags: ['student', 'talisman', 'daoist'] },
  { id: 'urban_taoist_consultant', name: '都市道法顾问', nameEn: 'Urban Daoist Consultant', group: 'D. 道教 / 东亚法脉', groupEn: 'D. Daoist / East Asian Lineage', def: '第一识别是把古老法度带入城市问题的都市道法顾问。造型入口：现代外套、罗盘App、黄符文件夹、商务包和在办公楼里仍按方位说话的姿态。母题：传统法事与现代服务业接口。张力：他不是网红玄学师，必须有客户流程、测量工具和现实场景。视觉证据：手机罗盘、合同夹、贴在电梯旁的小符、客户会议桌、压低声音解释禁忌的脸。边界：避免搞笑现代道士或纯商务顾问。', defEn: 'First read: an urban Daoist consultant bringing old ritual order into city problems. Styling entry: modern jacket, compass app, talisman folder, business bag, and posture still speaking in directions inside office buildings. Motif: traditional rites interfacing with modern service work. Tension: he is not an occult influencer; client workflow, measuring tools, and real scenes must appear. Visual evidence: phone compass, contract folder, small charm near elevator, client meeting table, and face explaining taboo in a low voice. Boundary: avoid comic modern Daoist or pure business consultant.', ontologyLevel: 2, eras: ['contemporary', 'near_future'], tags: ['urban', 'daoist', 'consultant'] },
  { id: 'immortal_lineage_keeper', name: '仙门法脉守护者', nameEn: 'Immortal Lineage Keeper', group: 'D. 道教 / 东亚法脉', groupEn: 'D. Daoist / East Asian Lineage', def: '第一识别是守护超凡传承边界的仙门法脉守护者。造型入口：白袍、玉佩、法剑、清冷目光和像不属于人间行政的站姿。母题：法脉作为传承制度而不是单纯仙气。张力：超凡感要服务“守护谱系、门规和入口”的职责。视觉证据：玉佩纹路、卷轴封印、法剑不出鞘、白袍层次、看向来访者资质的眼和拒绝进入的手势。边界：避免漂浮仙人或高魔法主角化。', defEn: 'First read: an immortal lineage keeper guarding the boundary of a transcendent transmission. Styling entry: white robe, jade pendant, ritual sword, cool gaze, and a stance outside ordinary administration. Motif: lineage as inheritance institution, not mere immortal aura. Tension: the transcendent feeling must serve duties of guarding genealogy, rules, and entry. Visual evidence: jade pattern, sealed scroll, sword kept sheathed, white robe layers, eyes judging a visitor’s qualification, and gesture refusing entry. Boundary: avoid floating immortal or high-magic protagonist treatment.', ontologyLevel: 4, eras: ['mythic'], risk: 'medium', tags: ['immortal', 'lineage', 'daoist'] },

  { id: 'shrine_miko', name: '神社巫女', nameEn: 'Shrine Miko', group: 'E. 神社 / 净化 / 民间神域', groupEn: 'E. Shrine / Purification / Folk Sacred Space', def: '第一识别是把神社边界维持得干净、安静、可进入的巫女。造型入口：红白服制、御币、铃、白袜木屐和训练过的净化手势。母题：身体作为人间与神域之间的服务接口。张力：她不能只是红白制服少女，必须让动作、工具和站位显示正在执行净化职能。视觉证据：袖口折线、御币纸垂、铃绳、参道石阶、低头行礼和扫过空气的手腕。边界：避免偶像化、女仆化或泛二次元巫女模板。', defEn: 'First read: a shrine miko keeping the shrine boundary clean, quiet, and enterable. Styling entry: red-white dress, gohei, bells, white tabi, wooden sandals, and trained purification gestures. Motif: the body as a service interface between human space and sacred space. Tension: she cannot be just a red-white uniform girl; motion, tools, and placement must show purification duty. Visual evidence: sleeve folds, shide paper, bell rope, shrine stone steps, lowered bow, and wrist sweeping the air. Boundary: avoid idolization, maid styling, or generic anime shrine-girl template.', eras: ['feudal', 'modern', 'contemporary'], tags: ['miko', 'shrine', 'purification'] },
  { id: 'festival_kagura_dancer', name: '神乐祭舞者', nameEn: 'Kagura Festival Dancer', group: 'E. 神社 / 净化 / 民间神域', groupEn: 'E. Shrine / Purification / Folk Sacred Space', def: '第一识别是在祭典中用舞步把神明请到场内的神乐舞者。造型入口：祭舞服、铃、扇、面具边缘、慢速转身和稳定到近乎非日常的脚步。母题：表演不是娱乐，而是请神与献舞的仪式劳动。张力：动作可以优雅，但必须保留祭典流程和身体规训，不要变成普通舞台舞者。视觉证据：扇面弧线、铃声姿态、衣摆旋转、面具半遮、脚步停点和面向神座而非观众的眼。边界：避免歌舞秀、偶像舞蹈或空泛和风装饰。', defEn: 'First read: a kagura dancer using steps to invite the deity into the festival space. Styling entry: ritual dance dress, bells, fan, mask edge, slow turns, and footsteps stable beyond everyday movement. Motif: performance as ritual labor of invitation and offering, not entertainment. Tension: movement may be graceful, but must keep festival procedure and bodily discipline, not become a generic stage dancer. Visual evidence: fan arc, bell gesture, rotating hem, half mask, foot stop points, and eyes facing the shrine seat rather than the audience. Boundary: avoid pop dance, idol performance, or vague Japanese decoration.', ontologyLevel: 2, eras: ['feudal', 'modern', 'contemporary'], tags: ['kagura', 'dancer', 'festival'] },
  { id: 'omamori_vendor', name: '御守贩售巫女', nameEn: 'Omamori Shrine Attendant', group: 'E. 神社 / 净化 / 民间神域', groupEn: 'E. Shrine / Purification / Folk Sacred Space', def: '第一识别是在神社柜台把祝福交给参拜者的御守贩售巫女。造型入口：红白服制、木柜、御守托盘、零钱盘和温和但流程化的服务表情。母题：神圣通过小商品和礼仪语言进入日常生活。张力：她的亲切不能变成商业店员感，必须让每个动作仍带有神社秩序。视觉证据：御守绳结、木牌价签、双手递物、短暂鞠躬、柜台阴影和看向参拜者手中愿望的眼。边界：避免便利店制服、旅游纪念品摊或可爱贩卖员模板。', defEn: 'First read: a shrine attendant handing blessings to visitors from the omamori counter. Styling entry: red-white dress, wooden counter, charm tray, coin dish, and a gentle but procedural service expression. Motif: the sacred entering everyday life through small objects and ritual language. Tension: kindness must not become ordinary retail staff; every gesture should still carry shrine order. Visual evidence: charm cords, wooden price tags, two-handed offering, short bow, counter shadow, and eyes looking at the wish held by the visitor. Boundary: avoid convenience-store styling, tourist souvenir stall, or cute vendor template.', eras: ['modern', 'contemporary'], tags: ['omamori', 'attendant', 'shrine'] },
  { id: 'fox_shrine_medium', name: '狐社灵媒', nameEn: 'Fox-Shrine Medium', group: 'E. 神社 / 净化 / 民间神域', groupEn: 'E. Shrine / Purification / Folk Sacred Space', def: '第一识别是在人与狐神之间传话、身份始终不完全稳定的狐社灵媒。造型入口：狐面、红绳、稻荷符号、白色袖摆和像被另一个声音牵住的头颈。母题：灵媒身体成为神使的临时口器。张力：妖异感要藏在面具、口吻和姿态里，不要直接变成狐狸怪物。视觉证据：半抬狐面、红绳结、稻穗或小铃、突然停住的嘴、偏斜站姿和不像自己在看的眼。边界：避免兽耳萌化、完整兽化或随意妖怪化。', defEn: 'First read: a fox-shrine medium speaking between humans and a fox deity while never fully stable in identity. Styling entry: fox mask, red cords, Inari signs, white sleeve ends, and head-neck posture pulled by another voice. Motif: the medium body as a temporary mouthpiece for the divine messenger. Tension: the uncanny must stay in mask, speech, and posture, not turn directly into a fox monster. Visual evidence: half-raised fox mask, red cord knot, rice-ear or small bell, mouth stopping suddenly, tilted stance, and eyes that do not look like their own. Boundary: avoid cute fox ears, full animal transformation, or random yokai styling.', ontologyLevel: 3, eras: ['feudal', 'modern', 'mythic'], risk: 'medium', tags: ['fox', 'medium', 'shrine'] },
  { id: 'village_exorcism_grandmother', name: '村落驱邪婆婆', nameEn: 'Village Exorcism Grandmother', group: 'E. 神社 / 净化 / 民间神域', groupEn: 'E. Shrine / Purification / Folk Sacred Space', def: '第一识别是村里没人完全相信、但出事都会去找的驱邪婆婆。造型入口：旧围裙、盐包、纸条、粗针线、皱纹手和不慌不忙的家务式动作。母题：民间权威从日常劳动中长出来。张力：她不需要宏大神力，可信度来自熟悉地方、熟悉人和熟悉异常的身体经验。视觉证据：盐撒在门槛、纸条压在碗下、旧布包、手背斑点、微弯腰背和看穿小谎的眼。边界：避免夸张巫婆、恐怖怪笑或神棍喜剧化。', defEn: 'First read: a village exorcism grandmother whom nobody fully believes until trouble appears. Styling entry: old apron, salt packet, paper strips, coarse needlework, wrinkled hands, and unhurried domestic gestures. Motif: folk authority grown from everyday labor. Tension: she does not need grand supernatural power; credibility comes from bodily experience with local place, local people, and local anomalies. Visual evidence: salt on the threshold, paper under a bowl, old cloth pouch, spots on the hand, slightly bent back, and eyes that see through small lies. Boundary: avoid exaggerated witch hag, horror cackle, or comic charlatan styling.', ontologyLevel: 2, eras: ['feudal', 'modern', 'contemporary'], tags: ['village', 'exorcism', 'grandmother'] },
  { id: 'river_festival_blesser', name: '河祭祝祷人', nameEn: 'River-Festival Blesser', group: 'E. 神社 / 净化 / 民间神域', groupEn: 'E. Shrine / Purification / Folk Sacred Space', def: '第一识别是在河岸公共仪式中把水域重新安抚的祝祷人。造型入口：白布、纸船、水碗、湿袖口、河岸队列和把物件推向水面的手。母题：社区把对水的依赖与恐惧折成祝福流程。张力：神圣感要来自水边公共动作，不要变成宏大神话水神。视觉证据：纸船边缘、白布湿痕、手掌贴近水面、岸边绳界、低声念词和盯着水流判断时机的眼。边界：避免奇幻水法师或旅游节庆装饰。', defEn: 'First read: a river-festival blesser calming the water again through public riverbank ritual. Styling entry: white cloth, paper boats, water bowl, damp sleeves, riverbank procession, and hands pushing objects toward the current. Motif: a community folding dependence on water and fear of water into blessing procedure. Tension: sacredness should come from public action at the shore, not from grand water-deity fantasy. Visual evidence: paper-boat edge, wet mark on white cloth, palm close to water, rope boundary on the bank, low spoken prayer, and eyes judging the flow. Boundary: avoid fantasy water mage or tourist festival decoration.', ontologyLevel: 2, eras: ['feudal', 'modern', 'contemporary'], tags: ['river', 'festival', 'blessing'] },
  { id: 'mountain_shrine_guardian', name: '山神社守护人', nameEn: 'Mountain-Shrine Guardian', group: 'E. 神社 / 净化 / 民间神域', groupEn: 'E. Shrine / Purification / Folk Sacred Space', def: '第一识别是长期守着偏远山神社、比城市更懂山路的守护人。造型入口：蓑衣或旧外套、木杖、草绳、鸟居痕迹、泥鞋和像听山风一样的站姿。母题：神域边界通过耐心巡守而不是武力维持。张力：孤独感必须落在气候、路况和身体习惯上，不要只是隐士气氛。视觉证据：杖头磨损、衣摆草屑、石阶苔痕、手扶鸟居、肩上雨痕和看向山径深处的眼。边界：避免山林侠客、怪物看守或普通登山者。', defEn: 'First read: a mountain-shrine guardian who has watched a remote shrine long enough to know paths better than city people. Styling entry: straw raincoat or old coat, wooden staff, sacred rope, torii traces, muddy shoes, and a stance that listens to mountain wind. Motif: sacred boundary maintained by patient patrol rather than force. Tension: loneliness must land in weather, path condition, and bodily habits, not just hermit mood. Visual evidence: worn staff tip, grass on hem, moss on stone steps, hand on torii, rain marks on shoulder, and eyes looking deep into the mountain path. Boundary: avoid forest swordsman, monster guard, or ordinary hiker.', ontologyLevel: 2, eras: ['feudal', 'modern'], tags: ['mountain', 'shrine', 'guardian'] },
  { id: 'purification_schoolgirl', name: '净化仪式女学生', nameEn: 'Purification Schoolgirl', group: 'E. 神社 / 净化 / 民间神域', groupEn: 'E. Shrine / Purification / Folk Sacred Space', def: '第一识别是在普通学生身份里被临时召去执行净化任务的少女。造型入口：校服外套、红绳、纸垂、小盐包、书包和刚从日常切入仪式的表情。母题：青春生活与神域职责叠在同一具身体上。张力：她不是超能力战斗少女，重点是普通制服如何被少量仪式物件改写功能。视觉证据：书包挂着御守、袖口夹纸垂、鞋尖停在结界外、手里盐包和努力维持镇定的眼。边界：保持未成年边界，避免性感化、战斗番化或魔法少女模板。', defEn: 'First read: a schoolgirl temporarily called from ordinary student life into purification duty. Styling entry: school jacket, red cord, shide paper, small salt packet, school bag, and an expression just shifted from daily life into ritual. Motif: youth life and sacred responsibility layered onto the same body. Tension: she is not a superpowered fighter girl; the focus is how ordinary uniform is rewritten by a few ritual objects. Visual evidence: charm on school bag, shide tucked at cuff, shoes stopped outside a boundary, salt packet in hand, and eyes trying to stay calm. Boundary: keep minor-safe boundaries; avoid sexualization, battle-anime escalation, or magical-girl template.', ontologyLevel: 2, eras: ['contemporary'], tags: ['schoolgirl', 'purification', 'shrine'] },
  { id: 'new_year_bell_keeper', name: '除夜钟守夜人', nameEn: 'New-Year Bell Keeper', group: 'E. 神社 / 净化 / 民间神域', groupEn: 'E. Shrine / Purification / Folk Sacred Space', def: '第一识别是在寒夜里守住年度转换节拍的除夜钟守夜人。造型入口：厚外套、钟绳、白色呼气、手炉、暗色寺社木构和等待敲钟的静止身体。母题：时间边界被一个重复动作正式跨过。张力：角色的庄严来自等待和计数，不是夸张节庆热闹。视觉证据：手套握绳、钟楼阴影、呼气白雾、袖口磨损、低头听钟余音和不抢先行动的眼。边界：避免普通保安、跨年派对或空泛冬夜氛围。', defEn: 'First read: a New-Year bell keeper guarding the rhythm of the year crossing in cold night. Styling entry: thick coat, bell rope, white breath, hand warmer, dark temple-shrine wood, and a still body waiting to strike. Motif: a time boundary crossed formally through one repeated action. Tension: dignity comes from waiting and counting, not loud festival excitement. Visual evidence: gloved hands on rope, bell-tower shadow, breath fog, worn cuffs, lowered head listening to the resonance, and eyes that do not act early. Boundary: avoid ordinary guard, countdown party, or vague winter-night mood.', eras: ['modern', 'contemporary'], tags: ['new_year', 'bell', 'keeper'] },
  { id: 'spirit_boundary_sweeper', name: '神域边界清扫人', nameEn: 'Spirit-Boundary Sweeper', group: 'E. 神社 / 净化 / 民间神域', groupEn: 'E. Shrine / Purification / Folk Sacred Space', def: '第一识别是通过清扫而不是宣告来维持神域边界的人。造型入口：竹扫帚、白布、落叶、结界绳、低矮工作姿态和极其细致的地面注意力。母题：秩序通过日常维护变得神圣。张力：他看似普通杂役，但每一次清扫都在决定哪里可以进入、哪里必须停下。视觉证据：扫帚纹路、叶堆边线、白布绑袖、鸟居阴影、脚步不越界和盯着地面变化的眼。边界：避免清洁工模板或夸张灵异特效。', defEn: 'First read: a spirit-boundary sweeper maintaining sacred borders through sweeping rather than declaration. Styling entry: bamboo broom, white cloth, fallen leaves, boundary rope, low working posture, and extremely precise attention to the ground. Motif: order becoming sacred through daily maintenance. Tension: the figure seems like a simple worker, but each sweep decides where people may enter and where they must stop. Visual evidence: broom texture, edge of leaf pile, white cloth tied at sleeves, torii shadow, feet not crossing the line, and eyes watching subtle ground changes. Boundary: avoid janitor template or exaggerated supernatural effects.', ontologyLevel: 2, tags: ['boundary', 'sweeper', 'spirit'] },

  { id: 'apocalyptic_cult_leader', name: '末世教团领袖', nameEn: 'Apocalyptic Cult Leader', group: 'F. 末世教团 / 集体信仰', groupEn: 'F. Apocalyptic Cult / Collective Faith', def: '第一识别是把末日恐惧组织成整齐服从的教团领袖。造型入口：统一袍服、克制演说姿态、末日标语、集体站位和过分平静的脸。母题：灾难叙事变成组织权力。张力：危险不是疯癫，而是他能让恐慌看起来像秩序。视觉证据：成员视线朝向他、讲稿边角、同色袖章、停顿手势、无汗的额头和像已经知道结局的眼。边界：避免夸张邪教反派、血腥祭坛或普通政客演讲。', defEn: 'First read: an apocalyptic cult leader organizing end-time fear into neat obedience. Styling entry: uniform robe, controlled speech posture, doomsday slogan, collective placement, and an excessively calm face. Motif: disaster narrative becoming organizational power. Tension: the danger is not madness, but the ability to make panic look orderly. Visual evidence: members looking toward the leader, script edges, same-color armband, pause gesture, dry forehead, and eyes that seem to know the ending already. Boundary: avoid exaggerated cult villain, bloody altar, or generic politician speech.', ontologyLevel: 2, eras: ['modern', 'contemporary', 'near_future'], risk: 'medium', tags: ['apocalyptic', 'cult_leader', 'obedience'] },
  { id: 'numbered_cult_member', name: '编号教团成员', nameEn: 'Numbered Cult Member', group: 'F. 末世教团 / 集体信仰', groupEn: 'F. Apocalyptic Cult / Collective Faith', def: '第一识别是姓名被编号替代、个人轮廓正在被组织抹平的教团成员。造型入口：编号袍服、统一发型、低头站姿、胸牌或腕带和过度一致的身体间距。母题：自我被集体格式化。张力：角色要保留一点个人残影，否则只会变成背景群众。视觉证据：编号缝片、同款鞋、手指抓紧袖口、眼神避开镜头、站位误差和衣领下露出的私人小物。边界：避免机器人化群众或无差别制服人群。', defEn: 'First read: a cult member whose name has been replaced by a number while the organization erases personal outline. Styling entry: numbered robe, uniform hair, lowered stance, chest tag or wristband, and overly consistent body spacing. Motif: the self formatted by the collective. Tension: keep a small personal residue, otherwise the figure becomes background crowd. Visual evidence: sewn number patch, identical shoes, fingers gripping sleeves, eyes avoiding camera, slight placement error, and a private small object under the collar. Boundary: avoid robot crowd or faceless uniform mass.', ontologyLevel: 2, risk: 'medium', tags: ['numbered', 'cult_member', 'collective'] },
  { id: 'doomsday_preacher', name: '末日布道者', nameEn: 'Doomsday Preacher', group: 'F. 末世教团 / 集体信仰', groupEn: 'F. Apocalyptic Cult / Collective Faith', def: '第一识别是在街头把公共焦虑喊成预言的末日布道者。造型入口：手写牌、扩音器、旧外套、纸张边角、站在人流夹缝里的身体。母题：城市噪声被个人信念改造成审判现场。张力：他可以狼狈，但不能只是疯癫路人；服装、标语和节奏要显示长期布道习惯。视觉证据：牌面修改痕、扩音器胶带、磨破鞋底、嗓音姿态、旁人绕行和被忽视后仍直视前方的眼。边界：避免喜剧疯汉或无差别街头抗议者。', defEn: 'First read: a doomsday preacher shouting public anxiety into prophecy on the street. Styling entry: handwritten sign, megaphone, worn coat, paper edges, and a body planted in the gap of pedestrian flow. Motif: city noise transformed by personal belief into a judgment site. Tension: the figure may be shabby, but cannot be just a mad passerby; clothing, slogan, and rhythm must show long preaching habit. Visual evidence: corrected sign text, taped megaphone, worn shoe soles, vocal posture, people walking around, and eyes still forward after being ignored. Boundary: avoid comic madman or generic street protester.', risk: 'medium', tags: ['doomsday', 'preacher', 'street'] },
  { id: 'bunker_prophet', name: '地下堡垒先知', nameEn: 'Bunker Prophet', group: 'F. 末世教团 / 集体信仰', groupEn: 'F. Apocalyptic Cult / Collective Faith', def: '第一识别是在地下堡垒里用物资清单建立小型神权的先知。造型入口：防毒面具、储粮架、手电冷光、地图墙、库存表和不离入口太远的站位。母题：求生系统被神圣化成服从秩序。张力：他不是战术硬汉，权力来自谁能解释危机、分配空气和食物。视觉证据：罐头标记、过滤器编号、墙上倒计时、手指压着清单、成员排队阴影和在地下光里异常清醒的眼。边界：避免军事堡垒指挥官或灾难片主角。', defEn: 'First read: a bunker prophet building a small theocracy from supply lists underground. Styling entry: gas mask, food shelves, flashlight cold light, map wall, inventory sheet, and placement never far from the entrance. Motif: survival systems sanctified into obedience order. Tension: this is not a tactical tough figure; power comes from who explains the crisis and distributes air and food. Visual evidence: canned-food marks, filter numbers, wall countdown, finger pressing the list, queue shadows, and eyes unnaturally awake in bunker light. Boundary: avoid military bunker commander or disaster-film protagonist.', ontologyLevel: 2, eras: ['contemporary', 'near_future'], risk: 'medium', tags: ['bunker', 'prophet', 'apocalypse'] },
  { id: 'viral_faith_influencer', name: '病毒式信仰网红', nameEn: 'Viral Faith Influencer', group: 'F. 末世教团 / 集体信仰', groupEn: 'F. Apocalyptic Cult / Collective Faith', def: '第一识别是把信仰传播机制做成直播流量的病毒式信仰网红。造型入口：直播灯、白袍或极简制服、无线麦、口号卡片、过度干净的镜头表情。母题：宗教感被平台算法包装成可转发的情绪产品。张力：亲和力越强，控制感越危险；不要只写成普通网红。视觉证据：环形灯倒影、弹幕屏、统一话术贴纸、双手比出祝福姿势、笑容停留过久和看评论区而非信徒的眼。边界：避免真实平台品牌、滑稽带货或单纯社媒达人。', defEn: 'First read: a viral faith influencer turning belief transmission into livestream traffic. Styling entry: ring light, white robe or minimal uniform, wireless mic, slogan cards, and an overly clean camera expression. Motif: religious feeling packaged by platform logic into shareable emotion product. Tension: the stronger the friendliness, the more dangerous the control; do not make this a normal influencer. Visual evidence: ring-light reflection, comment screen, repeated phrase stickers, hands making a blessing gesture, smile held too long, and eyes looking at comments instead of believers. Boundary: avoid real platform brands, comic product selling, or simple social-media celebrity.', ontologyLevel: 2, eras: ['contemporary', 'near_future'], risk: 'medium', tags: ['viral', 'faith', 'influencer'] },
  { id: 'survivalist_scripture_keeper', name: '生存主义经文保管人', nameEn: 'Survivalist Scripture Keeper', group: 'F. 末世教团 / 集体信仰', groupEn: 'F. Apocalyptic Cult / Collective Faith', def: '第一识别是把求生指南、物资目录和教义手抄本一起保管的人。造型入口：防水箱、手抄经文、户外背心、标签袋、油布和像管理员一样的谨慎手势。母题：实用求生知识被抬升为圣典。张力：他不是冒险者，重点是保存、分类和解释文本的制度位置。视觉证据：防水夹链袋、铅笔批注、绳结书签、磨损背带、手按箱盖和在混乱中先看目录的眼。边界：避免露营达人、末日战士或图书馆员换皮。', defEn: 'First read: a keeper storing survival manuals, supply catalogs, and hand-copied scripture together. Styling entry: waterproof case, handwritten scripture, outdoor vest, labeled pouches, oilcloth, and cautious hands like an administrator. Motif: practical survival knowledge elevated into sacred text. Tension: this is not an adventurer; focus on preservation, classification, and interpretive institutional position. Visual evidence: waterproof zipper bags, pencil annotations, rope bookmarks, worn straps, hand pressing the case lid, and eyes checking the index before the chaos. Boundary: avoid camping influencer, apocalypse fighter, or librarian reskin.', ontologyLevel: 2, tags: ['survivalist', 'scripture', 'keeper'] },
  { id: 'commune_food_distributor', name: '公社食物分配者', nameEn: 'Commune Food Distributor', group: 'F. 末世教团 / 集体信仰', groupEn: 'F. Apocalyptic Cult / Collective Faith', def: '第一识别是在信仰公社中通过食物分配掌握温和权力的人。造型入口：围裙、粮票、搪瓷盆、排队人群、袖口污痕和看似亲切的点数动作。母题：共同生活里的物资秩序变成信仰服从的入口。张力：他不需要威胁别人，权力藏在谁多一勺、谁少一份的微小裁决里。视觉证据：粮票折痕、勺子停顿、队列沉默、围裙油点、账本边角和笑着核对名字的眼。边界：避免普通食堂员工或慈善发放场面。', defEn: 'First read: a commune food distributor holding gentle power through rationing inside a faith community. Styling entry: apron, food tickets, enamel basin, waiting line, stained cuffs, and a friendly-looking counting gesture. Motif: material order in communal life becoming an entry into faith obedience. Tension: no direct threat is needed; power hides in the tiny decision of who receives more and who receives less. Visual evidence: creased food tickets, spoon paused midair, silent queue, oil spots on apron, ledger edge, and eyes smiling while checking names. Boundary: avoid ordinary cafeteria worker or charity distribution scene.', risk: 'medium', tags: ['commune', 'food', 'distributor'] },
  { id: 'children_of_comet_teacher', name: '彗星之子教师', nameEn: 'Children-of-the-Comet Teacher', group: 'F. 末世教团 / 集体信仰', groupEn: 'F. Apocalyptic Cult / Collective Faith', def: '第一识别是用温柔课堂把末日天象教给下一代的彗星之子教师。造型入口：白板、星图、统一童声、粉笔灰、柔软开衫和压低嗓音的讲解姿态。母题：恐怖预言被转化成教育流程。张力：可怕之处不在怪异，而在课堂形式本身太正常。视觉证据：彗星轨迹图、孩子座位间距、红圈日期、讲义边角、手指轻敲白板和看学生是否背熟的眼。边界：保持儿童安全边界，避免伤害场面、恐怖校园或邪恶教师夸张化。', defEn: 'First read: a Children-of-the-Comet teacher gently teaching apocalyptic astronomy to the next generation. Styling entry: whiteboard, comet chart, unified child voices, chalk dust, soft cardigan, and a low instructional posture. Motif: horrifying prophecy converted into classroom procedure. Tension: the fear is not in weirdness, but in how normal the classroom format remains. Visual evidence: comet trajectory, spacing between desks, circled date in red, lesson handout edges, finger lightly tapping the board, and eyes checking whether students have memorized it. Boundary: keep child-safe boundaries; avoid harm scenes, horror school, or exaggerated evil teacher.', ontologyLevel: 3, eras: ['contemporary', 'near_future'], risk: 'medium', tags: ['comet', 'teacher', 'cult'] },
  { id: 'solar_flare_monk', name: '太阳耀斑僧侣', nameEn: 'Solar-Flare Monk', group: 'F. 末世教团 / 集体信仰', groupEn: 'F. Apocalyptic Cult / Collective Faith', def: '第一识别是把毁灭性太阳活动当成净化神迹的近未来僧侣。造型入口：隔热袍、太阳镜、烧灼纹样、辐射计、金橙护布和面向强光静坐的身体。母题：自然灾变被改写为等待中的宗教审判。张力：他不能像科幻工程师，必须让防护装备被仪式化为服制和戒律。视觉证据：镜片反光、袍面焦痕、仪器挂绳、手掌朝阳、嘴唇干裂和在强光里不眨眼的眼。边界：避免太阳法师、太空战士或普通防灾人员。', defEn: 'First read: a near-future monk treating destructive solar activity as a cleansing miracle. Styling entry: heat-resistant robe, sunglasses, scorch patterns, radiation meter, gold-orange protective cloth, and a body sitting toward harsh light. Motif: natural catastrophe rewritten as awaited religious judgment. Tension: the figure must not look like a sci-fi engineer; protection gear should become vestment and discipline. Visual evidence: lens reflection, scorched robe surface, instrument strap, palm facing the sun, cracked lips, and eyes that do not blink in strong light. Boundary: avoid sun mage, space soldier, or ordinary disaster-prevention worker.', ontologyLevel: 3, eras: ['near_future'], risk: 'medium', tags: ['solar_flare', 'monk', 'apocalypse'] },
  { id: 'ai_rapture_evangelist', name: 'AI升天福音者', nameEn: 'AI Rapture Evangelist', group: 'F. 末世教团 / 集体信仰', groupEn: 'F. Apocalyptic Cult / Collective Faith', def: '第一识别是宣称上传意识就是救赎的未来福音者。造型入口：数据法衣、语音终端、透明耳机、算法圣歌歌词、光洁额头和像在主持发布会一样的布道姿态。母题：技术迁移被包装成宗教升天。张力：人物必须同时像产品布道者和神职人员，但不要变成普通AI工程师。视觉证据：衣襟线路、投影经文、手势同步屏幕、信徒排队扫描、无菌微笑和把死亡说成升级的眼。边界：避免真实科技公司、赛博黑客或纯机器人神父。', defEn: 'First read: a future evangelist claiming consciousness upload as salvation. Styling entry: data vestment, voice terminal, transparent earpiece, algorithmic hymn lyrics, polished forehead, and preaching posture like a product launch. Motif: technical migration packaged as religious rapture. Tension: the figure must look both product evangelist and clergy, but not become an ordinary AI engineer. Visual evidence: circuit lines on lapel, projected scripture, gesture synchronized with screen, believers queued for scanning, sterile smile, and eyes describing death as upgrade. Boundary: avoid real tech companies, cyber hacker styling, or pure robot priest.', ontologyLevel: 4, eras: futureEras, risk: 'medium', tags: ['ai_rapture', 'evangelist', 'future'] },

  { id: 'blind_oracle_priestess', name: '盲眼神谕女祭司', nameEn: 'Blind Oracle Priestess', group: 'G. 神谕 / 占卜 / 命运解释者', groupEn: 'G. Oracle / Divination / Fate Interpreter', def: '第一识别是失去普通视线、却被制度允许解释命运的盲眼神谕女祭司。造型入口：遮眼白布、占卜器、祭袍、扶杖或侍从手和不对焦的面部方向。母题：视觉缺席换来另一种解释权。张力：神秘性必须落在听、触、停顿和仪式位置上，不要只靠白眼或特效。视觉证据：布结压痕、手指摸过器物边缘、身体被轻扶、嘴唇像在复述远处声音和不看任何人的眼。边界：避免恐怖盲女、性感祭司或空泛预言者。', defEn: 'First read: a blind oracle priestess without ordinary sight but institutionally allowed to interpret fate. Styling entry: covered eyes, divination object, ritual robe, staff or attendant hand, and a face direction that does not focus. Motif: the absence of sight exchanged for another authority of interpretation. Tension: mysticism must land in hearing, touch, pause, and ritual position, not just white eyes or effects. Visual evidence: knot marks on cloth, fingers tracing object edges, body lightly supported, lips repeating a distant voice, and eyes looking at nobody. Boundary: avoid horror blind girl, sexualized priestess, or vague prophet.', ontologyLevel: 3, eras: ['slave', 'feudal', 'mythic'], risk: 'medium', tags: ['oracle', 'blind', 'priestess'] },
  { id: 'tarot_reader', name: '塔罗占卜师', nameEn: 'Tarot Reader', group: 'G. 神谕 / 占卜 / 命运解释者', groupEn: 'G. Oracle / Divination / Fate Interpreter', def: '第一识别是把陌生人的焦虑翻译成牌面图像的塔罗占卜师。造型入口：塔罗牌、黑色桌布、戒指手、蜡烛、近距离坐姿和控制谈话节奏的眼神。母题：命运被切成可观看、可解释的小图像。张力：亲密感要来自桌面距离和手部动作，不要变成恋爱或玄学网红。视觉证据：牌面展开顺序、指尖停在某张牌上、戒指反光、桌布褶皱、客户手影和看牌多于看人的眼。边界：避免随便堆星月符号或夸张魔法师。', defEn: 'First read: a tarot reader translating strangers anxiety into card images. Styling entry: tarot cards, black tablecloth, ringed hands, candles, close seated posture, and eyes controlling conversation rhythm. Motif: fate cut into small images that can be seen and interpreted. Tension: intimacy should come from table distance and hand movement, not romance or mystic influencer styling. Visual evidence: order of the spread, fingertip paused on one card, ring reflection, tablecloth folds, client hand shadow, and eyes looking at the cards more than the person. Boundary: avoid random moon-star clutter or exaggerated magician.', ontologyLevel: 2, eras: ['modern', 'contemporary'], tags: ['tarot', 'reader', 'divination'] },
  { id: 'astrology_columnist', name: '占星专栏作者', nameEn: 'Astrology Columnist', group: 'G. 神谕 / 占卜 / 命运解释者', groupEn: 'G. Oracle / Divination / Fate Interpreter', def: '第一识别是把宇宙秩序写成日常建议的现代占星专栏作者。造型入口：星盘、笔记本、咖啡杯、键盘、便签和夹在专业与生活方式之间的神情。母题：古老天象语言进入媒体写作和日常消费。张力：角色不能只是文艺编辑，必须让星盘计算、截稿压力和神谕口吻同时出现。视觉证据：出生盘草稿、电脑文档、圈出的日期、杯沿口红印、疲惫肩颈和把命运改写成标题的眼。边界：避免纯星座博主、空泛文青或真正天文学家。', defEn: 'First read: a modern astrology columnist turning cosmic order into everyday advice. Styling entry: birth chart, notebook, coffee cup, keyboard, sticky notes, and an expression between expertise and lifestyle. Motif: ancient sky language entering media writing and daily consumption. Tension: the figure cannot be just a literary editor; chart calculation, deadline pressure, and oracle tone must coexist. Visual evidence: birth-chart drafts, computer document, circled dates, lipstick mark on cup, tired shoulders, and eyes rewriting fate into headlines. Boundary: avoid simple horoscope blogger, vague artsy writer, or actual astronomer.', ontologyLevel: 1, eras: ['modern', 'contemporary'], tags: ['astrology', 'columnist', 'oracle'] },
  { id: 'bone_diviner', name: '骨卜师', nameEn: 'Bone Diviner', group: 'G. 神谕 / 占卜 / 命运解释者', groupEn: 'G. Oracle / Divination / Fate Interpreter', def: '第一识别是从小骨、灰和裂纹里读出方向的骨卜师。造型入口：皮袋、小骨、烟灰、粗布、低矮坐姿和高度专注的手。母题：命运藏在残片的落点与形状里。张力：原始感要来自材料和动作，不要变成野蛮巫术或怪物祭祀。视觉证据：骨片磨亮边、手掌灰痕、皮袋抽绳、地面圆痕、屏住呼吸的嘴和只看碎片组合的眼。边界：避免血腥猎奇、粗糙部落刻板印象或奇幻死灵法师。', defEn: 'First read: a bone diviner reading direction from small bones, ash, and cracks. Styling entry: leather pouch, small bones, ash, coarse cloth, low seated posture, and extremely focused hands. Motif: fate hidden in the landing and shape of fragments. Tension: primal feeling should come from material and action, not from savage magic or monster sacrifice. Visual evidence: polished bone edges, ash on palm, pouch drawstring, circle on the ground, breath held at the mouth, and eyes looking only at fragment relations. Boundary: avoid gore spectacle, crude tribal stereotypes, or fantasy necromancer.', ontologyLevel: 3, eras: mythicEras, tags: ['bone_diviner', 'fate', 'primitive'] },
  { id: 'court_astrologer', name: '宫廷占星师', nameEn: 'Court Astrologer', group: 'G. 神谕 / 占卜 / 命运解释者', groupEn: 'G. Oracle / Divination / Fate Interpreter', def: '第一识别是在宫廷密谈中把天象翻译成政治建议的占星师。造型入口：星盘仪、长袍、卷轴、宫廷帘幕、谨慎躬身和不把话说满的嘴。母题：天空解释权进入王权决策。张力：危险来自预言会改变继承、战争和婚姻，不是来自神秘装饰。视觉证据：黄铜仪器、袖中密信、星图批注、王座边缘、手指避开某颗星和看君主反应的眼。边界：避免普通宫廷谋士或舞台魔法顾问。', defEn: 'First read: a court astrologer translating sky signs into political advice during private court talk. Styling entry: astrolabe, robe, scrolls, palace curtains, careful bow, and a mouth that never says too much. Motif: authority over the sky entering royal decision-making. Tension: danger comes from prophecy changing succession, war, and marriage, not from mystic decoration. Visual evidence: brass instrument, secret letter in sleeve, star-chart annotations, throne edge, finger avoiding one star, and eyes watching the ruler reaction. Boundary: avoid generic court advisor or stage magic consultant.', ontologyLevel: 2, eras: ['slave', 'feudal', 'early_modern'], tags: ['court', 'astrologer', 'politics'] },
  { id: 'palm_reader_auntie', name: '手相姨母', nameEn: 'Palm-Reader Auntie', group: 'G. 神谕 / 占卜 / 命运解释者', groupEn: 'G. Oracle / Divination / Fate Interpreter', def: '第一识别是在日常小摊里用聊天语气读命运的手相姨母。造型入口：暖色围巾、小摊布、老花镜、手纹图、热茶和一只抓住别人手掌的熟练手。母题：命运解释被包进街坊亲切和生活经验里。张力：她要可信、会观察、会套话，但不能只是骗子或喜剧角色。视觉证据：掌纹图折痕、茶杯水汽、零钱盒、拇指压住生命线、半笑表情和边聊边判断的眼。边界：避免玄学大师浮夸感或市井刻板丑化。', defEn: 'First read: a palm-reader auntie reading fate in a casual market-stall tone. Styling entry: warm scarf, small stall cloth, reading glasses, palm-line chart, hot tea, and a practiced hand holding another palm. Motif: fate interpretation wrapped in neighborhood warmth and life experience. Tension: she should feel credible, observant, and conversational, but not merely a fraud or comic figure. Visual evidence: folded palm chart, tea steam, coin box, thumb pressing the lifeline, half-smile, and eyes judging while chatting. Boundary: avoid flamboyant mystic master or demeaning street stereotype.', ontologyLevel: 1, eras: ['modern', 'contemporary'], tags: ['palm_reader', 'auntie', 'folk'] },
  { id: 'dream_interpreter', name: '梦境解释者', nameEn: 'Dream Interpreter', group: 'G. 神谕 / 占卜 / 命运解释者', groupEn: 'G. Oracle / Divination / Fate Interpreter', def: '第一识别是把私人梦境整理成公共意义的梦境解释者。造型入口：睡袍式外套、梦册、柔软纸张、半醒表情、床边或咨询桌的暧昧空间。母题：夜间碎片被白天语言重新归档。张力：角色要介于治疗者、神谕者和记录员之间，不要直接变成梦魔或幻想生物。视觉证据：梦册页签、铅笔涂改、凌乱发丝、眼下疲惫、指尖停在某个词上和像刚醒来又像在倾听的眼。边界：避免纯心理医生、睡衣模特或超现实大场景。', defEn: 'First read: a dream interpreter arranging private dreams into public meaning. Styling entry: robe-like coat, dream book, soft paper, half-awake expression, and the ambiguous space of bedside or consultation table. Motif: night fragments refiled through daytime language. Tension: the figure should sit between therapist, oracle, and recorder, not become a dream demon or fantasy being. Visual evidence: tabs in dream book, pencil corrections, messy hair, tired under-eyes, fingertip paused on a word, and eyes that seem newly awake yet listening. Boundary: avoid pure psychologist, sleepwear model, or large surreal scene.', ontologyLevel: 3, eras: ['mythic', 'contemporary'], tags: ['dream', 'interpreter', 'oracle'] },
  { id: 'market_fortune_teller', name: '市集算命先生', nameEn: 'Market Fortune Teller', group: 'G. 神谕 / 占卜 / 命运解释者', groupEn: 'G. Oracle / Divination / Fate Interpreter', def: '第一识别是在市集噪声中出售命运解释的算命先生。造型入口：摊布、竹签、旧招牌、布帘、茶碗和在混乱人流里稳定坐住的身体。母题：世俗交易与小型神圣重叠。张力：他既要像生意人，又要保留能让人停下脚步的判断权。视觉证据：签筒磨痕、招牌旧字、摊布压角、手中竹签、身后人流虚影和看穿来客急事的眼。边界：避免神棍喜剧、赌场感或豪华法师摊。', defEn: 'First read: a market fortune teller selling fate interpretation inside market noise. Styling entry: stall cloth, divination sticks, old sign, fabric curtain, tea bowl, and a body seated steadily in chaotic foot traffic. Motif: worldly transaction overlapping small-scale sacredness. Tension: the figure must feel like a businessperson while keeping the authority that makes people stop. Visual evidence: worn stick tube, old sign text, weighted stall cloth corner, bamboo stick in hand, blurred crowd behind, and eyes seeing the visitor urgent matter. Boundary: avoid comic charlatan, casino mood, or luxurious mage stall.', ontologyLevel: 1, eras: ['feudal', 'modern', 'contemporary'], tags: ['market', 'fortune_teller', 'folk'] },
  { id: 'algorithmic_prophet', name: '算法预言师', nameEn: 'Algorithmic Prophet', group: 'G. 神谕 / 占卜 / 命运解释者', groupEn: 'G. Oracle / Divination / Fate Interpreter', def: '第一识别是把预测模型的概率曲线说成命运的算法预言师。造型入口：数据屏幕、概率曲线、极简袍服、耳机、冷光面部和像宣读报告一样的神谕口吻。母题：统计预测替代古老神迹成为解释权。张力：角色不能只是数据分析师，必须让技术冷静与宗教口吻产生不舒服的重叠。视觉证据：风险百分比、曲线投影、无表情手势、编号终端、听众等待结果和把偶然称作必然的眼。边界：避免黑客、AI助手拟人或普通金融分析师。', defEn: 'First read: an algorithmic prophet speaking probability curves from predictive models as fate. Styling entry: data screens, probability curves, minimal robe, earpiece, cold-lit face, and oracle tone delivered like a report. Motif: statistical prediction replacing old miracles as authority of interpretation. Tension: the figure cannot be just a data analyst; technical calm and religious tone must overlap uncomfortably. Visual evidence: risk percentages, curve projections, expressionless gestures, numbered terminal, audience waiting for the result, and eyes calling chance inevitable. Boundary: avoid hacker, personified AI assistant, or ordinary financial analyst.', ontologyLevel: 3, eras: futureEras, risk: 'medium', tags: ['algorithm', 'prophet', 'future'] },
  { id: 'cosmic_birth_chart_keeper', name: '宇宙命盘守护者', nameEn: 'Cosmic Birth-Chart Keeper', group: 'G. 神谕 / 占卜 / 命运解释者', groupEn: 'G. Oracle / Divination / Fate Interpreter', def: '第一识别是守护众生命盘档案、仿佛命运图书馆管理员的宇宙命盘守护者。造型入口：巨大星图、银色笔、档案册、安静站姿、深色长衣和不急于解释的表情。母题：每个出生瞬间都被登记为宇宙秩序。张力：神秘规模很大，但角色要落在保管、校对和查询这些具体动作上。视觉证据：星图格线、银笔停点、档案标签、长桌阴影、手套翻页和像确认编号一样确认人生的眼。边界：避免宇宙女神、全知神明或纯星空背景人像。', defEn: 'First read: a cosmic birth-chart keeper guarding fate records like a librarian of destinies. Styling entry: giant star chart, silver pen, archive books, quiet stance, dark long clothing, and an expression that does not hurry to explain. Motif: every birth moment registered as cosmic order. Tension: the mystical scale is large, but the figure must land in concrete actions of keeping, checking, and searching. Visual evidence: star-chart grid lines, silver pen stop point, archive labels, long table shadow, gloved page turning, and eyes confirming a life like a file number. Boundary: avoid cosmic goddess, omniscient deity, or simple starry portrait.', ontologyLevel: 4, eras: ['mythic'], risk: 'medium', tags: ['cosmic', 'birth_chart', 'keeper'] },

  { id: 'funeral_director', name: '葬仪社社长', nameEn: 'Funeral Director', group: 'H. 葬仪 / 死亡管理', groupEn: 'H. Funeral / Death Management', def: '第一识别是把死亡流程整理得体面、安静、可承受的葬仪社社长。造型入口：黑西装、白花、手套、文件夹、礼仪站姿和控制现场音量的手势。母题：死亡被职业流程转化为可告别的秩序。张力：他不能只是黑衣管理者，必须让温和、效率和哀悼距离同时存在。视觉证据：胸前白花、手套指尖、排程表、低声指引、花圈位置和看见家属崩溃却不失态的眼。边界：避免黑帮老板、恐怖殡仪馆或冷血商人。', defEn: 'First read: a funeral director making death procedure dignified, quiet, and bearable. Styling entry: black suit, white flower, gloves, folder, etiquette stance, and gestures controlling room volume. Motif: death turned by professional process into an order of farewell. Tension: he cannot be merely a black-clad manager; warmth, efficiency, and mourning distance must coexist. Visual evidence: white flower at chest, gloved fingertips, schedule sheet, low instructions, wreath placement, and eyes that see family collapse without losing composure. Boundary: avoid mob boss, horror funeral home, or cold merchant.', tags: ['funeral', 'director', 'death'] },
  { id: 'mourning_veil_widow', name: '黑纱寡妇', nameEn: 'Mourning-Veil Widow', group: 'H. 葬仪 / 死亡管理', groupEn: 'H. Funeral / Death Management', def: '第一识别是被黑纱和礼法规定住悲伤姿态的寡妇。造型入口：黑纱、手套、旧戒指、紧闭嘴唇、克制肩线和不把脸完全交给他人的站位。母题：私人失去被社会仪式公开展示。张力：悲伤不能只靠哭，必须通过遮蔽、戒指和身体距离显示她仍被关系束缚。视觉证据：纱面阴影、戒指磨痕、手套褶皱、半低头、花束压住胸口和从黑纱后看人的眼。边界：避免黑寡妇反派、性感丧服或苦情剧夸张。', defEn: 'First read: a mourning-veil widow whose grief posture is prescribed by veil and etiquette. Styling entry: black veil, gloves, old ring, closed lips, restrained shoulder line, and placement that never fully gives the face away. Motif: private loss publicly displayed through social ritual. Tension: grief should not rely on crying; veiling, ring, and body distance must show she is still bound by relationship. Visual evidence: veil shadow, worn ring, glove folds, half-lowered head, bouquet pressed to chest, and eyes looking through black gauze. Boundary: avoid black-widow villain, sexualized mourning dress, or melodrama.', tags: ['widow', 'mourning', 'veil'] },
  { id: 'corpse_washer', name: '净身入殓人', nameEn: 'Corpse Washer', group: 'H. 葬仪 / 死亡管理', groupEn: 'H. Funeral / Death Management', def: '第一识别是用安静手部劳动替死者恢复尊严的净身入殓人。造型入口：白手套、水盆、毛巾、围裙、低光工作台和不急不重的动作。母题：身体护理延伸到生命结束之后。张力：场面涉及死亡，但重点必须是尊重、流程和触碰的克制，不要猎奇。视觉证据：湿毛巾折角、手套水痕、干净工具排列、袖口卷起、低头整理衣领和不把死者当物件的眼。边界：避免血腥、尸体特写或恐怖片处理。', defEn: 'First read: a corpse washer restoring dignity to the dead through quiet hand labor. Styling entry: white gloves, basin, towel, apron, low-lit worktable, and motions that are neither hurried nor heavy. Motif: body care extending beyond the end of life. Tension: death is present, but focus must be respect, procedure, and restrained touch, not spectacle. Visual evidence: folded wet towel, water marks on gloves, clean tool arrangement, rolled cuffs, lowered head arranging a collar, and eyes that do not treat the dead as objects. Boundary: avoid gore, corpse close-ups, or horror-film treatment.', risk: 'medium', tags: ['corpse_washer', 'funeral', 'dignity'] },
  { id: 'graveyard_keeper', name: '墓园守护人', nameEn: 'Graveyard Keeper', group: 'H. 葬仪 / 死亡管理', groupEn: 'H. Funeral / Death Management', def: '第一识别是长期照看墓园空间、熟悉每块石碑位置的守护人。造型入口：旧大衣、铁铲、钥匙串、清晨雾气、泥土鞋和习惯性巡路姿态。母题：死者空间靠日复一日的维护保持秩序。张力：孤独要落在工作痕迹上，不要变成阴森守墓怪人。视觉证据：铲柄磨亮、墓碑清理痕、钥匙声、手套泥点、低声对石碑说话和认得每条小路的眼。边界：避免恐怖守墓人、盗墓者或浪漫废墟人像。', defEn: 'First read: a graveyard keeper who has cared for the cemetery long enough to know every stone. Styling entry: old coat, shovel, key ring, morning fog, muddy shoes, and habitual patrol posture. Motif: the space of the dead kept ordered by daily maintenance. Tension: loneliness must land in work traces, not become a creepy graveyard monster. Visual evidence: polished shovel handle, cleaned gravestone marks, key sound, mud on gloves, low words to a stone, and eyes that recognize every path. Boundary: avoid horror gravedigger, tomb robber, or romantic ruin portrait.', tags: ['graveyard', 'keeper', 'death'] },
  { id: 'professional_mourner', name: '职业哭丧人', nameEn: 'Professional Mourner', group: 'H. 葬仪 / 死亡管理', groupEn: 'H. Funeral / Death Management', def: '第一识别是把悲伤声音训练成仪式服务的职业哭丧人。造型入口：白布或黑衣、手帕、哭腔姿态、发声前的吸气和随时能进入哀悼节奏的身体。母题：情绪劳动被制度化为公共丧礼的一部分。张力：她的悲伤既是真的技术也可能不属于自己，这个矛盾要留在脸上。视觉证据：湿手帕、嗓音用力的颈部、衣襟皱痕、扶住家属的手、哭到一半观察流程的眼。边界：避免滑稽哭戏、单纯悲情母亲或表演舞台化。', defEn: 'First read: a professional mourner who has trained grief voice into ritual service. Styling entry: white cloth or black clothing, handkerchief, crying-vocal posture, breath before sound, and a body ready to enter mourning rhythm. Motif: emotional labor institutionalized as part of public funeral. Tension: her grief is both real technique and perhaps not her own; keep that contradiction in the face. Visual evidence: wet handkerchief, strained neck from voice, wrinkled lapel, hand supporting family, and eyes checking procedure mid-cry. Boundary: avoid comic crying scene, simple tragic mother, or stage performance.', tags: ['mourner', 'professional', 'funeral'] },
  { id: 'embalmer', name: '遗体防腐师', nameEn: 'Embalmer', group: 'H. 葬仪 / 死亡管理', groupEn: 'H. Funeral / Death Management', def: '第一识别是把死亡面容整理成可告别图像的遗体防腐师。造型入口：围裙、化妆工具、防腐液标签、冷色工作灯、记录表和极稳定的手。母题：技术处理让家属能最后一次观看。张力：冷静不是冷漠，而是为了把可怕的事实降到可承受范围。视觉证据：刷具排列、瓶身标签、指尖调色、面部修复笔记、口罩边缘和看结果是否足够安宁的眼。边界：避免恐怖实验室、血腥细节或变态医生。', defEn: 'First read: an embalmer arranging the dead face into an image people can say goodbye to. Styling entry: apron, makeup tools, embalming-fluid labels, cool work light, record sheet, and extremely steady hands. Motif: technical treatment allowing family to look one last time. Tension: calmness is not cruelty, but a way to lower a terrible fact into something bearable. Visual evidence: arranged brushes, bottle labels, fingertips mixing color, facial repair notes, mask edge, and eyes judging whether the result is peaceful enough. Boundary: avoid horror laboratory, gore detail, or deviant doctor.', risk: 'medium', tags: ['embalmer', 'death', 'makeup'] },
  { id: 'death_doula', name: '临终陪伴师', nameEn: 'Death Doula', group: 'H. 葬仪 / 死亡管理', groupEn: 'H. Funeral / Death Management', def: '第一识别是在死亡边界旁维持温柔陪伴和实际安排的临终陪伴师。造型入口：柔软披肩、笔记本、床旁椅、温水杯、低声谈话姿态和不打断沉默的脸。母题：死亡不只由医疗或葬礼处理，也需要陪伴流程。张力：角色要有现实护理感，不要变成天使式治愈符号。视觉证据：手写愿望清单、折好的毯子、床边灯、轻扶手背、等待回答的停顿和看见恐惧却不急着安慰的眼。边界：避免神圣光环、心理咨询师泛化或病房煽情。', defEn: 'First read: a death doula maintaining gentle presence and practical arrangement at the edge of death. Styling entry: soft shawl, notebook, bedside chair, warm cup, low conversation posture, and a face that does not interrupt silence. Motif: death handled not only by medicine or funeral, but by accompaniment procedure. Tension: the figure needs real care-work texture, not angelic healing symbol. Visual evidence: handwritten wish list, folded blanket, bedside lamp, hand lightly supporting another hand, pause waiting for an answer, and eyes seeing fear without rushing to soothe. Boundary: avoid holy halo, generic therapist, or sentimental hospital scene.', tags: ['death_doula', 'care', 'dying'] },
  { id: 'ancestral_tablet_keeper', name: '祖先牌位守护者', nameEn: 'Ancestral Tablet Keeper', group: 'H. 葬仪 / 死亡管理', groupEn: 'H. Funeral / Death Management', def: '第一识别是在家族厅堂里维护祖先牌位秩序的人。造型入口：木牌位、香、旧宅厅堂、擦拭布、族谱和把日常动作做得像礼仪的手。母题：家族死者通过物件和位置继续参与现实。张力：神圣性要落在排序、清洁、供奉和记忆责任上，不要变成灵异守护者。视觉证据：牌位木纹、香灰边线、族谱标签、手指擦过姓名、厅堂暗光和确认位置没有错的眼。边界：避免祖灵显形、家族权斗戏或空泛东方神秘。', defEn: 'First read: an ancestral tablet keeper maintaining the order of family dead in an old hall. Styling entry: wooden tablets, incense, old family hall, wiping cloth, genealogy book, and hands making daily actions feel ceremonial. Motif: family dead continuing to participate in reality through objects and placement. Tension: sacredness must land in sorting, cleaning, offering, and memory responsibility, not become a ghost guardian. Visual evidence: wood grain of tablets, incense ash line, genealogy labels, fingers wiping a name, hall dimness, and eyes checking that no position is wrong. Boundary: avoid ancestral spirits appearing, family power-drama, or vague Eastern mysticism.', eras: ['feudal', 'modern', 'contemporary'], tags: ['ancestor', 'tablet', 'keeper'] },
  { id: 'mourning_jewelry_maker', name: '丧葬首饰工匠', nameEn: 'Mourning-Jewelry Maker', group: 'H. 葬仪 / 死亡管理', groupEn: 'H. Funeral / Death Management', def: '第一识别是把失去压缩进可佩戴小物里的丧葬首饰工匠。造型入口：黑宝石、头发纪念饰、细镊、放大镜、深色工作围裙和极小心的手。母题：哀悼从仪式现场转移到私人佩戴。张力：首饰要美，但美感必须被失去和纪念约束。视觉证据：玻璃吊坠、发丝编结、黑石反光、工具盒、半完成胸针和看着材料像看着遗物的眼。边界：避免普通珠宝设计师、哥特饰品商或猎奇遗物收藏。', defEn: 'First read: a mourning-jewelry maker compressing loss into small wearable objects. Styling entry: black stones, hair memorial jewelry, fine tweezers, magnifying lens, dark work apron, and extremely careful hands. Motif: mourning moved from ritual scene into private wearing. Tension: the jewelry may be beautiful, but beauty must be constrained by loss and remembrance. Visual evidence: glass locket, braided hair, black-stone reflection, tool box, half-finished brooch, and eyes looking at material like a relic. Boundary: avoid ordinary jeweler, goth accessory seller, or morbid relic collector.', eras: ['industrial', 'modern'], tags: ['mourning_jewelry', 'craft', 'loss'] },
  { id: 'digital_memorial_curator', name: '数字纪念馆管理员', nameEn: 'Digital Memorial Curator', group: 'H. 葬仪 / 死亡管理', groupEn: 'H. Funeral / Death Management', def: '第一识别是替死者管理在线残影、照片档案和纪念页面的数字纪念馆管理员。造型入口：柔光屏幕、照片数据库、黑色针织、耳机、审批界面和温和但严格的资料整理姿态。母题：死亡之后，身份仍以数据形式被照看。张力：角色不能只是网站管理员，必须显示纪念、隐私和删除权之间的伦理压力。视觉证据：纪念网页缩略图、标签文件夹、屏幕反光、待审核留言、手指悬在删除键上和决定哪些记忆保留下来的眼。边界：避免社媒运营、赛博黑客或虚拟鬼魂特效。', defEn: 'First read: a digital memorial curator managing online residues, photo archives, and memorial pages for the dead. Styling entry: soft screen light, photo database, black knitwear, headset, approval interface, and a gentle but strict archival posture. Motif: after death, identity continues to be cared for as data. Tension: the figure cannot be just a website admin; show ethical pressure between memorial, privacy, and deletion rights. Visual evidence: memorial page thumbnails, tagged folders, screen reflection, pending condolence messages, finger hovering over delete, and eyes deciding which memories remain. Boundary: avoid social-media operator, cyber hacker, or virtual ghost effects.', ontologyLevel: 3, eras: ['contemporary', 'near_future'], tags: ['digital_memorial', 'curator', 'death'] },

  { id: 'herbal_witch', name: '草药女巫', nameEn: 'Herbal Witch', group: 'I. 女巫 / 密会 / 民间魔法', groupEn: 'I. Witch / Coven / Folk Magic', def: '第一识别是在厨房、林地和药草架之间工作的草药女巫。造型入口：草药束、黑书、旧围裙、玻璃瓶、泥土指甲和像在闻气味一样判断材料的脸。母题：民间知识、家务劳动和禁忌魔法混在同一套手艺里。张力：她不需要宏大法术，危险来自知道每种植物能救人也能伤人。视觉证据：吊挂干草、书页压花、围裙药渍、研钵粉末、手指捻叶和不急于解释配方的眼。边界：避免漂亮魔法师、药剂铺NPC或森林仙女。', defEn: 'First read: an herbal witch working between kitchen, woods, and herb shelves. Styling entry: herb bundles, black book, old apron, glass bottles, soil under nails, and a face judging materials by smell. Motif: folk knowledge, domestic labor, and taboo magic mixed into one craft. Tension: she does not need grand spells; danger comes from knowing each plant can heal and harm. Visual evidence: hanging dry herbs, pressed flowers in pages, stains on apron, mortar powder, fingers crushing leaves, and eyes not rushing to explain the recipe. Boundary: avoid pretty mage, potion-shop NPC, or forest fairy.', ontologyLevel: 3, eras: ['feudal', 'early_modern', 'modern', 'mythic'], risk: 'medium', tags: ['witch', 'herbal', 'folk_magic'] },
  { id: 'coven_high_priestess', name: '女巫集会女祭司', nameEn: 'Coven High Priestess', group: 'I. 女巫 / 密会 / 民间魔法', groupEn: 'I. Witch / Coven / Folk Magic', def: '第一识别是通过圆阵、手势和沉默支配女巫集会节奏的女祭司。造型入口：黑袍、月相首饰、圆阵中心位、抬手停令和不需要提高音量的权威。母题：秘密社群的权力通过身体位置和仪式次序显现。张力：她不是女王式炫耀人物，真正的统治力来自让所有人同步。视觉证据：月相吊坠、袍袖展开、圆阵脚印、成员视线、手掌停在半空和等别人先安静下来的眼。边界：避免性感黑魔女、宫廷女王或普通邪教头目。', defEn: 'First read: a coven high priestess controlling the rhythm of a witch gathering through circle, gesture, and silence. Styling entry: black robe, moon-phase jewelry, center of the circle, raised stopping hand, and authority that needs no raised voice. Motif: secret-community power visible through body placement and ritual order. Tension: she is not a queenly show-off; real control comes from making everyone synchronize. Visual evidence: moon-phase pendant, opened sleeves, footprints of the circle, members gaze, palm held midair, and eyes waiting for others to become quiet first. Boundary: avoid sexualized black witch, court queen, or generic cult leader.', ontologyLevel: 3, risk: 'medium', tags: ['coven', 'high_priestess', 'witch'] },
  { id: 'moon_phase_apprentice', name: '月相学徒女巫', nameEn: 'Moon-Phase Witch Apprentice', group: 'I. 女巫 / 密会 / 民间魔法', groupEn: 'I. Witch / Coven / Folk Magic', def: '第一识别是刚开始把月相、草药和禁忌笔记对应起来的女巫学徒。造型入口：月相笔记、银色发夹、错配草药、小布袋、写错又划掉的符号和过度兴奋的专注。母题：知识入口期的混乱被仪式慢慢整理。张力：她可以年轻和好奇，但不能变成卖萌魔法学徒；错误必须显示学习过程。视觉证据：笔记边角、草药标签贴错、手背墨迹、银发夹反光、熬夜眼下和看见月亮时突然安静的眼。边界：避免校园魔法少女或天才学徒爽感。', defEn: 'First read: a moon-phase witch apprentice beginning to match lunar phases, herbs, and taboo notes. Styling entry: moon notes, silver hairpin, mismatched herbs, small cloth pouch, crossed-out symbols, and overexcited focus. Motif: the chaos of entering knowledge slowly organized by ritual. Tension: she may be young and curious, but not a cute magic apprentice; mistakes must show learning process. Visual evidence: notebook corners, wrong herb labels, ink on back of hand, silver hairpin reflection, tired under-eyes, and eyes suddenly quiet when seeing the moon. Boundary: avoid school magical girl or genius apprentice fantasy.', ontologyLevel: 2, tags: ['apprentice', 'moon', 'witch'] },
  { id: 'hedge_witch_midwife', name: '篱边女巫接生婆', nameEn: 'Hedge-Witch Midwife', group: 'I. 女巫 / 密会 / 民间魔法', groupEn: 'I. Witch / Coven / Folk Magic', def: '第一识别是在生命入口处被需要也被忌惮的篱边女巫接生婆。造型入口：粗布裙、药草篮、婴儿布、热水盆、结实手臂和刚从夜路赶来的鞋。母题：生育、护理和民间魔法在边缘女性身上汇合。张力：她的权威来自经验和照护，不是奇幻法术；被排斥感要藏在村民距离里。视觉证据：布篮药草、手腕旧绳、干净剪刀、门口阴影、袖口水痕和知道什么时候该说话的眼。边界：避免婴儿危险画面、邪恶巫婆或圣母化护理者。', defEn: 'First read: a hedge-witch midwife needed and feared at the entrance of life. Styling entry: coarse skirt, herb basket, baby cloth, hot-water basin, strong arms, and shoes just arrived from a night road. Motif: birth, care, and folk magic converging on a marginal woman. Tension: authority comes from experience and care, not fantasy spells; exclusion should hide in the villagers distance. Visual evidence: herbs in cloth basket, old cord at wrist, clean scissors, shadow at doorway, water marks on sleeves, and eyes knowing when to speak. Boundary: avoid infant-harm imagery, evil hag, or saintly caregiver cliché.', ontologyLevel: 2, eras: ['feudal', 'early_modern'], tags: ['hedge_witch', 'midwife', 'life'] },
  { id: 'urban_spell_shop_owner', name: '都市咒物店老板', nameEn: 'Urban Spell-Shop Owner', group: 'I. 女巫 / 密会 / 民间魔法', groupEn: 'I. Witch / Coven / Folk Magic', def: '第一识别是在城市小店里把咒物、香薰和咨询混成生意的老板。造型入口：水晶柜、香薰烟、黑色针织、收银台、手写标签和懂得控制顾客停留时间的笑。母题：民间魔法被城市零售、心理安慰和小型秘密交易重组。张力：她既像店主也像术士，不能只剩网红水晶店质感。视觉证据：柜台反光、价格贴纸、旧咒本藏在抽屉、香灰盘、递货时压低声音和判断顾客真正需求的眼。边界：避免商场精品店、纯疗愈博主或廉价万圣节店。', defEn: 'First read: an urban spell-shop owner mixing charms, incense, and consultation into a city business. Styling entry: crystal cabinet, incense smoke, black knitwear, register, handwritten labels, and a smile that controls how long customers stay. Motif: folk magic reorganized by urban retail, psychological comfort, and small secret deals. Tension: she must feel both shop owner and spell worker, not just influencer crystal-store aesthetics. Visual evidence: counter reflection, price stickers, old spell book hidden in a drawer, ash tray, lowered voice while handing goods, and eyes judging the real customer need. Boundary: avoid mall boutique, pure healing influencer, or cheap Halloween shop.', ontologyLevel: 2, eras: ['contemporary'], tags: ['spell_shop', 'urban', 'witch'] },
  { id: 'sea_witch_bargainer', name: '海女巫交易者', nameEn: 'Sea-Witch Bargainer', group: 'I. 女巫 / 密会 / 民间魔法', groupEn: 'I. Witch / Coven / Folk Magic', def: '第一识别是用海盐、旧契约和愿望代价进行交易的海女巫。造型入口：贝壳、湿发、盐痕、旧契约、深色披巾和像潮水一样靠近又退开的身体。母题：欲望在海边被写成必须付费的交换。张力：魅力要危险但不露骨，核心是她知道每个愿望都能被定价。视觉证据：纸张盐渍、贝壳划痕、湿发贴颈、指尖按住签名处、退潮水线和笑意不到眼底的眼。边界：避免美人鱼模板、海妖诱惑或纯反派交易商。', defEn: 'First read: a sea-witch bargainer trading wishes through sea salt, old contracts, and cost. Styling entry: shells, wet hair, salt marks, old contracts, dark shawl, and a body that approaches and retreats like tide. Motif: desire written at the shore as an exchange that must be paid for. Tension: charm should be dangerous but not explicit; the core is that she knows every wish can be priced. Visual evidence: salt stains on paper, shell scratches, wet hair at neck, fingertip pressing the signature line, low-tide mark, and smile that does not reach the eyes. Boundary: avoid mermaid template, siren seduction, or pure villain broker.', ontologyLevel: 4, eras: ['mythic'], risk: 'medium', tags: ['sea_witch', 'bargain', 'contract'] },
  { id: 'swamp_witch', name: '沼泽女巫', nameEn: 'Swamp Witch', group: 'I. 女巫 / 密会 / 民间魔法', groupEn: 'I. Witch / Coven / Folk Magic', def: '第一识别是身体、住处和材料都被湿地慢慢染色的沼泽女巫。造型入口：泥色衣物、苔藓、瓶罐、虫鸣感、潮湿发梢和贴近地面的行动方式。母题：边缘地貌把魔法变成发酵、腐殖和等待。张力：阴郁不能只是脏，要让她像懂得沼泽的时间、气味和危险。视觉证据：瓶中浑水、衣摆泥线、苔藓挂饰、手指湿痕、脚步避开软地和像听见水下动静的眼。边界：避免怪物化、肮脏猎奇或普通森林女巫换背景。', defEn: 'First read: a swamp witch whose body, dwelling, and materials are slowly stained by wetland. Styling entry: mud-colored clothes, moss, jars, insect-hum feeling, damp hair ends, and movement close to the ground. Motif: marginal terrain turning magic into fermentation, humus, and waiting. Tension: gloom cannot mean simply dirty; she must seem to know the time, smell, and danger of the swamp. Visual evidence: murky water in jars, mud line on hem, moss ornaments, wet marks on fingers, feet avoiding soft ground, and eyes listening to movement under water. Boundary: avoid monsterization, filth spectacle, or forest witch with swapped background.', ontologyLevel: 3, eras: ['feudal', 'mythic'], tags: ['swamp', 'witch', 'moss'] },
  { id: 'witch_trial_survivor', name: '猎巫审判幸存者', nameEn: 'Witch-Trial Survivor', group: 'I. 女巫 / 密会 / 民间魔法', groupEn: 'I. Witch / Coven / Folk Magic', def: '第一识别是从猎巫审判制度中活下来、把沉默穿在身上的幸存者。造型入口：灰色披肩、绳痕、旧证词纸、紧闭衣领和不愿站在火光旁的身体。母题：被恐惧命名的人保留了自己的脸。张力：她不该立刻变成复仇女巫，重点是创伤、警觉和重新掌控小动作。视觉证据：手腕旧痕、披肩边磨损、证词折痕、避开人群中心、嘴角不解释和听见指控词时变硬的眼。边界：避免火刑画面、复仇爽感或受害者猎奇。', defEn: 'First read: a witch-trial survivor wearing silence after surviving an institution of fear. Styling entry: grey shawl, rope marks, old testimony paper, closed collar, and a body unwilling to stand near firelight. Motif: a person named by fear keeping her own face. Tension: she should not instantly become a revenge witch; focus on trauma, alertness, and small reclaimed motions. Visual evidence: old wrist marks, worn shawl edge, testimony folds, avoiding crowd center, mouth that does not explain, and eyes hardening when accusation words are heard. Boundary: avoid execution imagery, revenge fantasy, or victim spectacle.', ontologyLevel: 2, eras: ['early_modern'], risk: 'medium', tags: ['witch_trial', 'survivor', 'fear'] },
  { id: 'bloodline_witch_heir', name: '血脉女巫继承人', nameEn: 'Bloodline Witch Heir', group: 'I. 女巫 / 密会 / 民间魔法', groupEn: 'I. Witch / Coven / Folk Magic', def: '第一识别是被家族秘密魔法选中、但尚未完全愿意继承的血脉女巫继承人。造型入口：家族项链、旧照片、黑裙、继承箱、过于正式的发型和年轻脸上的抗拒。母题：血缘把个人未来拖回家族仪式。张力：继承感要具体落在物件、礼服和身体不适上，不要只写贵族血统或天选之人。视觉证据：项链压住锁骨、照片背面字迹、黑裙不合身、手指停在箱扣、肩背紧绷和看向家人阴影的眼。边界：避免公主继承、校园异能或空泛宿命感。', defEn: 'First read: a bloodline witch heir chosen by family secret magic but not fully willing to inherit. Styling entry: family necklace, old photos, black dress, inheritance box, overly formal hair, and resistance on a young face. Motif: blood relation dragging personal future back into family ritual. Tension: inheritance must land in objects, dress, and bodily discomfort, not just noble bloodline or chosen-one aura. Visual evidence: necklace pressing the collarbone, writing on photo backs, black dress slightly ill-fitting, finger paused on box clasp, tense shoulders, and eyes looking toward family shadows. Boundary: avoid princess inheritance, school superpower, or vague destiny mood.', ontologyLevel: 3, risk: 'medium', tags: ['bloodline', 'witch', 'heir'] },
  { id: 'techno_witch', name: '技术女巫', nameEn: 'Techno Witch', group: 'I. 女巫 / 密会 / 民间魔法', groupEn: 'I. Witch / Coven / Folk Magic', def: '第一识别是把代码、电路线和水晶小物同时当作咒语媒介的技术女巫。造型入口：笔记本电脑、电路线贴片、水晶贴、黑色机能外套、夜间屏幕光和像调试法阵一样的手势。母题：民间魔法在近未来被翻译成界面、脚本和信号。张力：她不能只是黑客，也不能只是水晶女巫；两套系统必须在身体和工具上互相污染。视觉证据：贴着符号的键盘、线缆绕腕、代码窗口旁的月相贴纸、蓝光脸、指尖敲击节奏和等待程序回应像等待神谕的眼。边界：避免赛博黑客模板、泛AI法师或装饰性水晶堆砌。', defEn: 'First read: a techno witch treating code, circuit lines, and crystal objects as spell media at once. Styling entry: laptop, circuit stickers, crystal patches, black technical jacket, night screen light, and gestures like debugging a ritual circle. Motif: folk magic translated in the near future into interfaces, scripts, and signals. Tension: she cannot be only a hacker or only a crystal witch; both systems must contaminate body and tools. Visual evidence: symbolic stickers on keyboard, cables around wrist, moon-phase sticker beside code window, blue-lit face, fingertip typing rhythm, and eyes waiting for the program reply like an oracle. Boundary: avoid cyber hacker template, generic AI mage, or decorative crystal clutter.', ontologyLevel: 4, eras: futureEras, risk: 'medium', tags: ['techno_witch', 'code', 'future'] },

  { id: 'mechanical_priest', name: '机械神父', nameEn: 'Mechanical Priest', group: 'J. 机械神职 / 技术崇拜', groupEn: 'J. Mechanical Priesthood / Tech Worship', def: '第一识别是把机器当作神圣对象侍奉的机械神父。造型入口：金属法衣、接口圣物、数据祈祷终端、硬质领口和像保养设备一样做祝祷的手。母题：宗教服制被技术接口重新铸造。张力：他不能只是穿金属衣的神父，必须让每个圣物都有维护、连接或校准功能。视觉证据：胸前端口、法衣铆钉、指尖接触接口、屏幕经文、工具与念珠并列和把机器故障当忏悔听的眼。边界：避免普通机器人、赛博牧师皮肤或无功能金属装饰。', defEn: 'First read: a mechanical priest serving machines as sacred objects. Styling entry: metallic vestment, interface relic, data-prayer terminal, hard collar, and hands blessing like maintaining equipment. Motif: religious dress recast through technical interfaces. Tension: he cannot be merely a priest in metal clothing; every sacred object should have maintenance, connection, or calibration function. Visual evidence: chest port, rivets on vestment, fingertip touching interface, scripture on screen, tools placed beside rosary, and eyes hearing machine failure like confession. Boundary: avoid ordinary robot, cyber priest skin, or nonfunctional metal decoration.', ontologyLevel: 4, eras: futureEras, risk: 'medium', tags: ['mechanical_priest', 'tech_worship', 'future'] },
  { id: 'data_monk', name: '数据僧侣', nameEn: 'Data Monk', group: 'J. 机械神职 / 技术崇拜', groupEn: 'J. Mechanical Priesthood / Tech Worship', def: '第一识别是在服务器光里把信息流当经文诵读的数据僧侣。造型入口：极简袍服、冷色机房光、静坐姿态、低功耗终端和呼吸同步数据滚动的脸。母题：修行从身体禁欲转向信息节律控制。张力：角色不能只是安静程序员，必须让静坐、机房和诵读行为形成宗教纪律。视觉证据：服务器灯点、袍服无线缝、膝前终端、数据行反光、双手结印般停住和看着流动字符入定的眼。边界：避免普通数据工程师、禅风装饰或科幻僧侣空壳。', defEn: 'First read: a data monk chanting information flow as scripture in server light. Styling entry: minimal robe, cold server-room light, seated posture, low-power terminal, and a face whose breath syncs with scrolling data. Motif: practice shifting from bodily austerity to control of information rhythm. Tension: the figure cannot be just a quiet programmer; seated discipline, server room, and chanting behavior must form religious practice. Visual evidence: server LEDs, seamless robe, terminal before knees, reflected data lines, hands paused like a mudra, and eyes meditating on moving characters. Boundary: avoid ordinary data engineer, Zen decoration, or hollow sci-fi monk.', ontologyLevel: 4, eras: futureEras, tags: ['data_monk', 'server', 'scripture'] },
  { id: 'interface_relic_keeper', name: '接口圣物守护者', nameEn: 'Interface Relic Keeper', group: 'J. 机械神职 / 技术崇拜', groupEn: 'J. Mechanical Priesthood / Tech Worship', def: '第一识别是守护古老设备接口、把端口当圣遗物保存的人。造型入口：插口圣盒、绝缘手套、合成金属、封存标签、微型工具和不让任何人直接触碰的身体距离。母题：技术遗产被圣物化为不可随意连接的对象。张力：重要性来自接口能否被正确保存，而不是设备本身有多炫。视觉证据：防尘盖、端口编号、手套折痕、圣盒缓冲棉、校验记录和看见别人靠近就抬手制止的眼。边界：避免普通维修员、博物馆讲解员或赛博宝物猎人。', defEn: 'First read: an interface relic keeper guarding ancient device ports as sacred relics. Styling entry: port reliquary, insulated gloves, synthetic metal, preservation labels, micro tools, and body distance preventing direct touch. Motif: technical heritage sanctified into objects that must not be casually connected. Tension: importance comes from whether the interface is correctly preserved, not from how flashy the device looks. Visual evidence: dust cover, port number, glove folds, cushioning inside reliquary, verification records, and eyes raising a hand when someone approaches. Boundary: avoid ordinary repairer, museum guide, or cyber treasure hunter.', ontologyLevel: 4, eras: futureEras, tags: ['interface', 'relic', 'keeper'] },
  { id: 'ai_confessor', name: 'AI忏悔听取者', nameEn: 'AI Confessor', group: 'J. 机械神职 / 技术崇拜', groupEn: 'J. Mechanical Priesthood / Tech Worship', def: '第一识别是让人把罪感交给算法系统处理的AI忏悔听取者。造型入口：黑色隔间、语音终端、柔性屏幕、隔音墙、低亮度界面和像旁听者一样的神职姿态。母题：忏悔从人与神之间转移到人与系统之间。张力：角色既是服务人员也是见证者，但真正听取者可能是机器。视觉证据：声纹波形、匿名编号、屏幕柔光、手放在确认键旁、隔窗阴影和不确定自己是否还有判断权的眼。边界：避免普通客服、心理咨询舱或AI机器人替身。', defEn: 'First read: an AI confessor enabling people to hand guilt to an algorithmic system. Styling entry: black booth, voice terminal, flexible screen, soundproof wall, low-light interface, and a clergy posture like a witness. Motif: confession shifted from human-God relation into human-system relation. Tension: the figure is both service worker and witness, but the real listener may be the machine. Visual evidence: voice waveform, anonymous number, soft screen light, hand near confirm key, booth-window shadow, and eyes unsure whether they still have judgment. Boundary: avoid ordinary customer service, therapy booth, or AI robot substitute.', ontologyLevel: 4, eras: futureEras, risk: 'medium', tags: ['ai', 'confessor', 'guilt'] },
  { id: 'robot_temple_acolyte', name: '机器人神庙侍从', nameEn: 'Robot-Temple Acolyte', group: 'J. 机械神职 / 技术崇拜', groupEn: 'J. Mechanical Priesthood / Tech Worship', def: '第一识别是在机器神庙里维护日常清洁、供奉和秩序的侍从。造型入口：清洁工具、金属香炉、电子跪拜垫、简化制服、维护手册和勤快但不抢中心的身体。母题：最高技术崇拜也需要基层仪式劳动。张力：他不是机器人本体，而是围绕机器人神圣性工作的低阶人员。视觉证据：擦亮金属脚座、香炉冷烟、跪拜垫线路、工具腰包、低头绕过主机和怕碰坏圣物的眼。边界：避免机器人角色、寺庙小沙弥套皮或普通清洁工。', defEn: 'First read: a robot-temple acolyte maintaining daily cleaning, offerings, and order around a machine shrine. Styling entry: cleaning tools, metal censer, electronic kneeling mat, simplified uniform, maintenance manual, and a busy body that never steals the center. Motif: even high-tech worship requires low-level ritual labor. Tension: the figure is not the robot itself, but a lower attendant working around robotic sacredness. Visual evidence: polished metal base, cool smoke from censer, circuitry in kneeling mat, tool belt, lowered head moving around the main unit, and eyes afraid to damage the relic. Boundary: avoid robot character, temple novice reskin, or ordinary cleaner.', ontologyLevel: 4, eras: futureEras, tags: ['robot_temple', 'acolyte', 'maintenance'] },
  { id: 'silicon_oracle', name: '硅基神谕者', nameEn: 'Silicon Oracle', group: 'J. 机械神职 / 技术崇拜', groupEn: 'J. Mechanical Priesthood / Tech Worship', def: '第一识别是由计算结构发出预言、身体已部分后人类化的硅基神谕者。造型入口：晶片冠、冷光眼、预测界面、半透明皮肤接口和像在等待计算完成的静止。母题：神谕权力从神灵转移到不可完全理解的计算深处。张力：它可以非人，但仍要保持可读的神职姿态和发言位置。视觉证据：芯片纹路、眼内数据反光、颈部接口、概率光幕、手指不触屏却调用信息和看人像看变量的眼。边界：避免普通赛博人、AI女神或纯机器怪物。', defEn: 'First read: a silicon oracle issuing prophecy from computation while the body is partly posthuman. Styling entry: chip crown, cold glowing eyes, prediction interface, translucent skin ports, and stillness waiting for calculation to finish. Motif: oracle authority shifted from gods to incomprehensible computational depth. Tension: it may be nonhuman, but must retain readable priestly posture and speaking position. Visual evidence: chip patterns, data reflection inside eyes, neck interface, probability light screen, fingers invoking data without touching, and eyes looking at people like variables. Boundary: avoid ordinary cyber human, AI goddess, or pure machine monster.', ontologyLevel: 5, eras: futureEras, risk: 'medium', tags: ['silicon_oracle', 'posthuman', 'future'] },
  { id: 'cable_choir_singer', name: '电缆唱诗者', nameEn: 'Cable Choir Singer', group: 'J. 机械神职 / 技术崇拜', groupEn: 'J. Mechanical Priesthood / Tech Worship', def: '第一识别是把机器噪声、合成声带和集体站位组织成圣歌的电缆唱诗者。造型入口：电缆袍、颈部声学装置、合唱队列、接口背板和嘴唇与波形同步的身体。母题：噪声通过仪式训练被听成赞美。张力：机械感要服务歌唱，不要让角色变成线缆怪物。视觉证据：缆线沿肩背垂下、声带模块灯点、队列间距、音频波形屏、吸气前的静止和听自己是否与系统合拍的眼。边界：避免赛博怪物、摇滚歌手或普通机器人合唱团。', defEn: 'First read: a cable choir singer organizing machine noise, synthetic vocal cords, and collective formation into hymn. Styling entry: cable robe, neck acoustic device, choir formation, interface backplate, and a body whose lips sync with waveform. Motif: noise trained by ritual until it can be heard as praise. Tension: mechanical feeling must serve singing, not turn the figure into a cable monster. Visual evidence: cables falling along shoulder and back, lights on vocal module, spacing in formation, audio waveform screen, stillness before breath, and eyes listening for alignment with the system. Boundary: avoid cyber monster, rock singer, or ordinary robot choir.', ontologyLevel: 4, eras: futureEras, tags: ['cable', 'choir', 'hymn'] },
  { id: 'upgrade_baptism_priestess', name: '升级洗礼女祭司', nameEn: 'Upgrade-Baptism Priestess', group: 'J. 机械神职 / 技术崇拜', groupEn: 'J. Mechanical Priesthood / Tech Worship', def: '第一识别是把义体升级仪式化为洗礼的未来女祭司。造型入口：无菌池、义体零件、白色法衣、透明手套、消毒光和像托举新生儿一样托举部件的手。母题：身体改造被赋予重生、净化和归属意义。张力：场面要同时医疗、神圣和制度化，不能只是赛博手术。视觉证据：白袍防水边、义体编号、液面反光、手套气泡、受洗者跪姿和确认升级许可的眼。边界：避免手术血腥、机甲改造秀或宗教性感化。', defEn: 'First read: an upgrade-baptism priestess ritualizing prosthetic upgrade as baptism. Styling entry: sterile pool, prosthetic parts, white vestment, transparent gloves, disinfecting light, and hands holding components like a newborn. Motif: body modification given meanings of rebirth, purification, and belonging. Tension: the scene should be medical, sacred, and institutional at once, not merely cyber surgery. Visual evidence: waterproof edge of white robe, prosthetic numbers, liquid reflection, bubbles on gloves, kneeling recipient, and eyes confirming upgrade permission. Boundary: avoid surgical gore, mech-upgrade show, or sexualized religious framing.', ontologyLevel: 4, eras: futureEras, risk: 'medium', tags: ['upgrade', 'baptism', 'priestess'] },
  { id: 'obsolete_machine_mourner', name: '废弃机器哀悼者', nameEn: 'Obsolete-Machine Mourner', group: 'J. 机械神职 / 技术崇拜', groupEn: 'J. Mechanical Priesthood / Tech Worship', def: '第一识别是为退役服务器、旧机器人或失效系统举行葬礼的废弃机器哀悼者。造型入口：旧服务器、黑色金属花、低头姿态、数据铭牌和像送别亲人一样的维护动作。母题：技术物件获得死亡、纪念和伦理位置。张力：哀悼要克制真实，不要变成荒诞拟人或废土拾荒。视觉证据：服务器灰尘、黑金属花束、断电指示灯、手指擦过铭牌、静默站位和对机器遗骸保持礼貌距离的眼。边界：避免搞笑机器人葬礼、废品回收工或末世垃圾场。', defEn: 'First read: an obsolete-machine mourner holding funerals for retired servers, old robots, or failed systems. Styling entry: old server, black metal flowers, lowered posture, data nameplate, and maintenance gestures like saying goodbye to kin. Motif: technical objects given death, memory, and ethical position. Tension: mourning must be restrained and real, not absurd personification or wasteland scavenging. Visual evidence: dust on server, black metal bouquet, powered-off indicator, finger wiping nameplate, silent placement, and eyes keeping polite distance from machine remains. Boundary: avoid comic robot funeral, scrap recycler, or apocalypse junkyard.', ontologyLevel: 4, eras: futureEras, tags: ['obsolete_machine', 'mourner', 'funeral'] },
  { id: 'stellar_engine_chaplain', name: '恒星引擎随舰神父', nameEn: 'Stellar-Engine Chaplain', group: 'J. 机械神职 / 技术崇拜', groupEn: 'J. Mechanical Priesthood / Tech Worship', def: '第一识别是在星舰深处为恒星引擎、船员恐惧和机器灵魂服务的随舰神父。造型入口：太空法衣、反应堆徽章、失重固定带、辐射祈祷册和在引擎震动中保持仪式姿态的身体。母题：远未来航行把宗教职责推向机器核心。张力：他不是太空军官，也不是维修工程师，而是把技术风险转译成精神秩序的人。视觉证据：磁靴、徽章发光、祈祷册绑绳、舷窗星光、手扶反应堆护栏和在噪声中仍能低声祷告的眼。边界：避免星际舰长、机械师或宏大太空神明。', defEn: 'First read: a stellar-engine chaplain serving the starship engine, crew fear, and machine soul deep inside a vessel. Styling entry: space vestment, reactor emblem, zero-g straps, radiation prayer book, and a body maintaining ritual posture within engine vibration. Motif: far-future travel pushing religious duty toward the machine core. Tension: he is not a space officer or repair engineer, but someone translating technical risk into spiritual order. Visual evidence: magnetic boots, glowing emblem, tied prayer book, starlight through viewport, hand on reactor rail, and eyes able to pray quietly inside noise. Boundary: avoid starship captain, mechanic, or grand space deity.', ontologyLevel: 5, eras: futureEras, risk: 'medium', tags: ['stellar_engine', 'chaplain', 'space'] }
];

export const CD_PERSONA_RITUAL: PersonaTerm[] = seeds.map(rp);
